// =====================================================================
// KISAH BOS BARU: asal-usul tujuh bos arc 2 "Benang Sepi" (Juragan Topeng
// sampai Dalang Sepi), diceritakan sebagai misi sampingan berantai setelah
// bos itu kalah. Bentuk data sama persis dengan cerita/kisah.js
// (mesin: js/99z-kisah-npc.js):
//   { tipe: "bicara",   npc, tujuan, baris, tanya? }
//   { tipe: "pandu",    npc, area, ke: [tx, ty], tujuan, ajak, baris }
//   { tipe: "kalahkan", monster, need, area?, tujuan, baris? }
//   { tipe: "prasasti", area, dekat: "bos" | [tx, ty], tujuan, baris }
// Titik `ke` tiap langkah pandu sudah dicek pada peta hasil build() area itu
// (dengan S.teka/buka kosong & tekaBeres = false): petak tidak padat, bukan tepi
// peta, bukan benda hiasan padat, dan terjangkau BFS (4 arah, petak tidak padat)
// dari posisi awal NPC maupun dari semua posisi jadwal hariannya.
// =====================================================================
"use strict";

const KISAH_BOS_BARU = [
  // ===================== JURAGAN TOPENG =====================
  {
    id: "juraganTopeng", npc: "kadir", monster: "juraganTopeng",
    judul: ["Topeng Tanpa Cap", "The Unstamped Masks"],
    syarat: () => S.bos && S.bos.juraganTopeng,
    hadiah: { gold: 3000, exp: 20000, serpih: 6 },
    ringkas: ["Juragan Topeng dulunya Darsa, pemahat topeng di Labuhan Lama. Tiga puluh tahun lalu, peti-peti topeng buatannya untuk Pesta Laut ditahan Syahbandar Kadir muda karena suratnya kurang satu cap, lalu membusuk kehujanan di gudang pabean. Darsa ditertawakan sekota dan bangkrut. Sejak itu ia hidup dari selundupan dan tak pernah lagi melepas topengnya. Dalang Sepi menawarinya kendi untuk mengurung suara-suara yang dulu menertawakannya. Di balik semua itu, ia masih memberi roti kepada anak-anak gang.", "The Mask Smuggler was once Darsa, a mask carver of the Old Harbor City. Thirty years ago, his crates of masks for the Sea Festival were held by a young Harbormaster Kadir because the papers lacked one stamp, and they rotted in the rain in the customs shed. The whole town laughed at Darsa and he went bankrupt. From then on he lived by smuggling and never again took off his mask. The Silent Puppeteer offered him jars to imprison the voices that once laughed at him. Beneath it all, he still gave bread to the alley children."],
    langkah: [
      { tipe: "bicara", npc: "kadir", tujuan: ["Dengarkan pengakuan Syahbandar Kadir tentang Juragan Topeng", "Hear Harbormaster Kadir's confession about the Mask Smuggler"], baris: [
        ["kadir", ["Ah, kau. Duduk, duduk. Jangan di situ, itu tumpukan surat muatan. Duduk di peti itu saja. ...Itu juga surat? Ya sudah, berdiri saja.", "Ah, it's you. Sit, sit. Not there, that's a pile of cargo papers. Sit on that crate. ...Papers too? Fine, just stand."]],
        ["kadir", ["Sejak Juragan Topeng kalah, aku tidak bisa tidur. Bukan karena takut. Karena aku tahu siapa orang di balik topeng itu. Aku tahu sejak pertama kali mendengar namanya.", "Since the Mask Smuggler was beaten, I can't sleep. Not from fear. Because I know who was behind that mask. I've known since the first time I heard the name."]],
        ["kadir", ["Namanya Darsa. Pemahat topeng. Dulu kiosnya di ujung dermaga, paling ramai di seluruh pelabuhan. Topeng buatannya bisa tersenyum dan menangis, tergantung dari mana kau melihatnya.", "His name was Darsa. A mask carver. His stall stood at the end of the pier, the busiest in the whole harbor. His masks could smile or weep, depending on where you looked at them from."]],
        ["hero", ["Bapak mengenalnya?", "You knew him?"]],
        ["kadir", ["Lebih buruk dari itu, Nak. Akulah yang membuatnya menjadi Juragan Topeng. Dengan satu cap. Satu cap yang tidak kuberikan.", "Worse than that, child. I'm the one who made him the Mask Smuggler. With one stamp. One stamp I didn't give."]],
        ["kadir", ["Ikut aku ke dermaga. Ada cerita yang tidak bisa kuceritakan di antara tumpukan kertas. Kertas-kertas ini sudah cukup banyak menyusahkan orang.", "Come with me to the pier. There's a story I can't tell among stacks of paper. These papers have caused people enough trouble already."]],
      ], tanya: [
        { tanya: ["Kenapa Bapak tidak bilang sebelum saya masuk gudang?", "Why didn't you tell me before I went into the warehouse?"], jawab: [
          ["kadir", ["Karena aku pengecut, Nak. Kalau kubilang, kau akan bertanya kenapa. Dan aku harus menjawab. Tiga puluh tahun aku menghindari pertanyaan itu, seperti menghindari kapal tanpa surat.", "Because I'm a coward, child. If I'd told you, you'd have asked why. And I would have had to answer. For thirty years I've dodged that question, the way I dodge ships without papers."]],
        ] },
      ] },
      // ke [20, 26]: petak pasir dermaga selatan (x 20, y 26), terjangkau BFS dari Kadir (7, 13) & semua posisi jadwalnya
      { tipe: "pandu", npc: "kadir", area: "labuhan", ke: [20, 26], tujuan: ["Ikuti Syahbandar Kadir ke dermaga selatan", "Follow Harbormaster Kadir to the south pier"],
        ajak: ["Ke dermaga. Jangan jalan terlalu cepat, orang-orang nanti mengira aku sedang ditangkap.", "To the pier. Don't walk too fast, people will think I'm being arrested."], baris: [
        ["kadir", ["Di sini dulu berdiri gudang pabean. Sudah dirobohkan lama sekali. Tiga puluh tahun lalu, Darsa membawa dua puluh peti topeng ke sini. Topeng untuk Pesta Laut, pesta terbesar di Labuhan.", "The customs shed used to stand here. It was torn down long ago. Thirty years ago, Darsa brought twenty crates of masks here. Masks for the Sea Festival, the biggest celebration in the harbor."]],
        ["kadir", ["Aku baru tiga bulan jadi syahbandar. Muda, kaku, dan bangga pada aturan. Surat muatannya lengkap... kecuali satu cap dari kantor kabupaten. Satu cap.", "I'd been harbormaster for only three months. Young, stiff, and proud of the rules. His cargo papers were complete... except for one stamp from the regency office. One stamp."]],
        ["kadir", ["Aku menahan peti-petinya sampai capnya datang. Lalu hujan turun tiga hari tiga malam. Atap gudang bocor. Waktu cap itu akhirnya tiba, semua topengnya sudah lapuk dan berjamur.", "I held his crates until the stamp came. Then it rained for three days and three nights. The shed roof leaked. When the stamp finally arrived, every mask had rotted and grown mold."]],
        ["hero", ["Dan Pesta Laut?", "And the Sea Festival?"]],
        ["kadir", ["Berjalan tanpa topeng. Orang-orang mengejeknya. 'Darsa Tanpa Cap!' teriak anak-anak di pasar. Ia menjual kiosnya untuk membayar utang kayu. Lalu ia menghilang. Bertahun-tahun kemudian, muncul kabar tentang penyelundup yang tak pernah melepas topengnya.", "It went on without masks. People mocked him. 'Darsa No-Stamp!' the children shouted in the market. He sold his stall to pay his timber debts. Then he vanished. Years later came rumors of a smuggler who never took off his mask."]],
        ["kadir", ["Ia tidak pernah meminta izin lagi untuk apa pun. Tidak pernah lagi menunggu cap siapa pun. Kau mengerti sekarang? Gudang selundupan itu adalah jawabannya untukku.", "He never asked permission for anything again. Never again waited for anyone's stamp. Do you understand now? That smuggler's warehouse was his answer to me."]],
        ["kadir", ["Anak buahnya masih bersembunyi di gudang itu. Usir mereka, lalu periksa ruang juragan. Darsa selalu memahat di kayu kalau hatinya penuh. Mungkin ia meninggalkan sesuatu.", "His men are still hiding in that warehouse. Drive them out, then search the boss's room. Darsa always carved into wood when his heart was full. Maybe he left something behind."]],
      ] },
      { tipe: "kalahkan", monster: "begalTopeng", need: 6, area: "gudang", tujuan: ["Usir 6 Begal Bertopeng yang masih bersembunyi di Gudang Labuhan", "Drive out 6 Masked Bandits still hiding in the Harbor Warehouse"], baris: [
        ["narasi", ["Begal terakhir menjatuhkan sesuatu sebelum kabur lewat jendela: sebuah topeng kecil yang belum dicat. Pahatannya halus sekali. Separuh wajahnya tersenyum, separuh lagi belum selesai.", "The last bandit drops something before fleeing through a window: a small, unpainted mask. The carving is very fine. Half its face is smiling; the other half is unfinished."]],
        ["hero", ["(Topeng ini bukan buatan pabrik. Ada yang memahatnya dengan sabar... dan berhenti di tengah jalan.)", "(This mask wasn't mass-made. Someone carved it patiently... and stopped halfway.)"]],
      ] },
      { tipe: "prasasti", area: "gudang", dekat: "bos", tujuan: ["Cari pahatan Darsa di ruang juragan", "Find Darsa's carving in the boss's room"], baris: [
        ["narasi", ["Di tiang kayu dekat bekas kursi juragan, tersembunyi di balik tumpukan kendi pecah, ada pahatan yang dalam dan rapi. Dari bekas pisau-pisaunya, pahatan ini dibuat bertahun-tahun, sedikit demi sedikit.", "On a wooden post near the boss's old chair, hidden behind piles of broken jars, is a deep and careful carving. From the knife marks, it was made over many years, little by little."]],
        ["narasi", ["'Aku Darsa. Dulu aku memahat wajah untuk orang lain. Sekarang aku memahat wajah untuk diriku sendiri, supaya tak ada yang melihat wajah asliku ditertawakan lagi.'", "'I am Darsa. Once I carved faces for other people. Now I carve a face for myself, so no one will ever see my real face being laughed at again.'"]],
        ["narasi", ["'Orang bertopeng tanpa wajah datang membawa kendi. Katanya: kurung saja suara yang menertawakanmu. Tanpa suara, tak ada ejekan. Kedengarannya adil.'", "'A faceless masked man came bearing jars. He said: just lock away the voices that laughed at you. Without voices, there is no mockery. It sounded fair.'"]],
        ["narasi", ["'Tapi kendi-kendi itu makin banyak. Nyanyian pesinden, tawa kuli, tangis bayi. Mereka tidak pernah menertawakanku. Aku lupa kapan aku berhenti membalas dendam dan mulai sekadar mencuri.'", "'But the jars kept multiplying. A singer's song, porters' laughter, babies' cries. They never laughed at me. I forget when I stopped taking revenge and started simply stealing.'"]],
        ["narasi", ["Di bagian paling bawah, huruf-hurufnya lebih kecil, seperti ditulis sambil ragu: 'Syahbandar muda itu tidak tertawa. Ia hanya taat aturan. Entah kenapa, itu yang paling menyakitkan.'", "At the very bottom, the letters are smaller, as if written in hesitation: 'The young harbormaster didn't laugh. He only followed the rules. Somehow, that hurt the most.'"]],
        ["hero", ["Darsa...", "Darsa..."]],
      ] },
      { tipe: "bicara", npc: "galang", tujuan: ["Tanyakan kepada Galang apa yang ia tahu tentang juragan", "Ask Galang what he knows about the boss"], baris: [
        ["galang", ["Kak! Kakak habis dari gudang lagi? Ngapain? Kendinya kan sudah pecah semua.", "Hey! You went back to the warehouse? What for? All the jars are broken already."]],
        ["hero", ["Galang, kau pernah melihat Juragan Topeng dari dekat, kan? Seperti apa dia?", "Galang, you've seen the Mask Smuggler up close, right? What was he like?"]],
        ["galang", ["Hmm... Jangan bilang Syahbandar, ya. Waktu aku masih tidur di atap gudang kain, ada orang bertopeng yang tiap subuh menaruh roti di talang. Selalu tiga potong. Pas untuk aku dan dua temanku.", "Hmm... Don't tell the Harbormaster, okay? Back when I slept on the cloth warehouse roof, a masked man left bread in the gutter every dawn. Always three pieces. Exactly enough for me and my two friends."]],
        ["galang", ["Kukira dia orang baik yang malu. Ternyata dia juragan penyelundup. Aneh, ya, Kak? Orang yang mencuri suara satu kota, tapi tidak pernah lupa jumlah anak di atap.", "I thought he was a shy good person. Turns out he was the smuggler boss. Weird, isn't it? A man who stole a whole town's voices, but never forgot how many kids were on the roof."]],
        ["hero", ["Mungkin karena dia tahu rasanya ditertawakan dan sendirian.", "Maybe because he knew what it's like to be laughed at and alone."]],
        ["galang", ["Kalau ketemu dia lagi, bilang terima kasih untuk rotinya, ya. ...Tapi suaranya Nyi Merdu tetap tidak boleh dicuri! Itu beda urusan!", "If you ever meet him again, tell him thanks for the bread. ...But stealing Nyi Merdu's voice is still not okay! That's a different matter!"]],
      ] },
      { tipe: "bicara", npc: "kadir", tujuan: ["Ceritakan isi pahatan Darsa kepada Syahbandar Kadir", "Tell Harbormaster Kadir what Darsa carved"], baris: [
        ["hero", ["Pak, Darsa meninggalkan pahatan. Ia menulis bahwa Bapak tidak menertawakannya. Bapak hanya taat aturan. Dan itulah yang paling menyakitkan baginya.", "Pak, Darsa left a carving. He wrote that you didn't laugh at him. You only followed the rules. And that hurt him the most."]],
        ["kadir", ["...Ya. Ya, itu adil. Orang yang tertawa paling tidak melihatmu. Orang yang hanya membaca surat bahkan tidak melihatmu sama sekali.", "...Yes. Yes, that's fair. A person who laughs at least sees you. A person who only reads papers doesn't see you at all."]],
        ["hero", ["Galang bilang, juragan itu tiap subuh menaruh roti untuk anak-anak di atap.", "Galang says the boss left bread for the rooftop kids every dawn."]],
        ["kadir", ["Roti... Hah. Tangan pemahat itu masih tahu cara memberi. Ke mana pun ia pergi setelah topengnya pecah, kuharap tangan itu masih bisa memegang pahat.", "Bread... Hah. That carver's hands still knew how to give. Wherever he went after his mask broke, I hope those hands can still hold a chisel."]],
        ["kadir", ["Lihat ini. Surat izin kios di ujung dermaga, untuk pemahat topeng mana pun yang mau berjualan di Pesta Laut tahun depan. Sudah kucap. Tiga cap, malah. Satu untuk tiap sepuluh tahun aku terlambat.", "Look at this. A stall permit at the end of the pier, for any mask carver who wants to sell at next year's Sea Festival. Already stamped. Three stamps, in fact. One for every ten years I was late."]],
        ["kadir", ["Aturan tetap penting, Nak. Tanpa aturan, pelabuhan ini kacau. Tapi aturan dibuat untuk melindungi orang, bukan untuk menenggelamkan mereka. Butuh tiga puluh tahun bagiku untuk mengerti. Terimalah ini, dan jangan butuh selama itu.", "Rules still matter, child. Without rules, this harbor would be chaos. But rules are made to protect people, not to drown them. It took me thirty years to understand. Take this, and don't take that long yourself."]],
      ] },
    ],
  },

  // ===================== KUDA SEMBRANI =====================
  {
    id: "kudaSembrani", npc: "inaSeli", monster: "kudaSembrani",
    judul: ["Kuda yang Tak Pernah Diikat", "The Horse That Was Never Tied"],
    syarat: () => S.bos && S.bos.kudaSembrani,
    hadiah: { gold: 3600, exp: 26000, serpih: 7 },
    ringkas: ["Menurut cerita rakyat Jawa, Kuda Sembrani adalah kuda bersayap yang dapat terbang di angkasa. Di Sabana Timur, Sembrani putih datang pada kemarau terpanjang dan membawa awan hujan di bawah sayapnya. Para leluhur pembangun megalit bersumpah tak akan pernah mengikatnya, dan menyusun lingkaran batu di Bukit Sembrani sebagai 'kandang tanpa pagar'. Benang Dalang Sepi adalah tali pertama yang pernah menjeratnya; karena itulah ia menghitam dan mengamuk. Ibu Lewa pernah dituntunnya pulang dari badai pasir.", "In Javanese folklore, the Kuda Sembrani is a winged horse able to fly through the sky. In the Eastern Savanna, a white Sembrani came during the longest drought, carrying rain clouds beneath its wings. The megalith-building ancestors swore never to tie it, and raised the stone ring on Sembrani Hill as a 'pen without a fence'. The Silent Puppeteer's thread was the first rope ever to bind it; that's why it turned black and raged. It once guided Lewa's mother home through a sandstorm."],
    langkah: [
      { tipe: "bicara", npc: "inaSeli", tujuan: ["Dengarkan kisah Ina Seli tentang Kuda Sembrani", "Hear Ina Seli's tale of the Kuda Sembrani"], baris: [
        ["inaSeli", ["Kemarilah, Nak. Duduk di dekat alat tenunku. Dengar? Di luar sana masih gerimis. Sudah tiga hari. Rumput mulai ingat caranya hijau.", "Come here, child. Sit by my loom. Hear that? It's still drizzling out there. Three days now. The grass is beginning to remember how to be green."]],
        ["inaSeli", ["Menurut cerita rakyat Jawa, Kuda Sembrani adalah kuda bersayap yang bisa terbang di angkasa. Dalam banyak kisah, ia menjadi tunggangan tokoh-tokoh mulia. Cerita itu dibawa pedagang dari barat, dan orang di sini menyukainya.", "In Javanese folklore, the Kuda Sembrani is a winged horse that can fly through the sky. In many tales it carries noble heroes. Traders brought that story from the west, and people here grew fond of it."]],
        ["inaSeli", ["Tapi Sembrani di bukit kami punya kisah sendiri. Kisah yang tidak ditulis, melainkan ditenun. Benang demi benang, nenek ke ibu, ibu ke anak.", "But the Sembrani on our hill has a story of its own. A story not written, but woven. Thread by thread, grandmother to mother, mother to daughter."]],
        ["inaSeli", ["Dahulu kala, kemarau berlangsung tujuh tahun. Sumur kering, kerbau mati, anak-anak lupa bunyi hujan. Lalu suatu senja, seekor kuda putih bersayap turun ke bukit. Di bawah sayapnya, ia membawa awan.", "Long ago, a drought lasted seven years. Wells dried up, buffalo died, children forgot the sound of rain. Then one dusk, a white winged horse came down onto the hill. Beneath its wings, it carried clouds."]],
        ["hero", ["Dan hujan turun?", "And the rain came?"]],
        ["inaSeli", ["Hujan turun. Dan para leluhur melakukan satu hal yang sangat bijak, Nak. Mereka tidak mencoba menangkapnya. Ikut aku ke kubur batu di tengah kampung. Ada yang harus kau lihat dengan matamu sendiri.", "The rain came. And the ancestors did something very wise, child. They didn't try to catch it. Come with me to the stone tombs in the middle of the village. There's something you must see with your own eyes."]],
      ], tanya: [
        { tanya: ["Ina, kenapa kudanya jadi hitam?", "Ina, why did the horse turn black?"], jawab: [
          ["inaSeli", ["Sabar, Nak. Benang yang ditarik dari tengah akan kusut. Kita mulai dari ujungnya dulu. Jawabannya ada di akhir kain.", "Patience, child. A thread pulled from the middle tangles. We start from its end. The answer is at the far edge of the cloth."]],
        ] },
      ] },
      // ke [19, 8]: petak jalan batu di pelataran kubur batu (x 15-24, y 6-11), terjangkau BFS dari Ina Seli (14, 10) & semua posisi jadwalnya
      { tipe: "pandu", npc: "inaSeli", area: "kampungBatu", ke: [19, 8], tujuan: ["Ikuti Ina Seli ke pelataran kubur batu", "Follow Ina Seli to the stone tomb plaza"],
        ajak: ["Pelan-pelan saja. Kakiku sudah tua, tapi masih hafal jalan ke kubur leluhur.", "Slowly now. My feet are old, but they still know the way to the ancestors' tombs."], baris: [
        ["inaSeli", ["Lihat pahatan di sisi kubur batu yang paling tua ini. Kuda bersayap, dan di sekelilingnya tangan-tangan manusia yang terbuka. Tidak ada satu pun yang menggenggam tali.", "Look at the carving on the side of this oldest stone tomb. A winged horse, and around it open human hands. Not a single one holds a rope."]],
        ["inaSeli", ["Para leluhur bersumpah: Sembrani tidak boleh diikat. Tidak dengan tali, tidak dengan pagar, tidak dengan janji yang dipaksakan. Ia datang karena ia mau. Ia pergi karena ia mau.", "The ancestors swore: the Sembrani must never be tied. Not with rope, not with fences, not with forced promises. It comes because it wishes to. It leaves because it wishes to."]],
        ["inaSeli", ["Lalu mereka menyusun lingkaran batu di bukit utara. Kandang tanpa pagar, begitu kami menyebutnya. Tempat ia boleh beristirahat, dengan celah di antara batu-batunya supaya ia selalu bisa pergi.", "Then they arranged a stone ring on the northern hill. A pen without a fence, we call it. A place where it may rest, with gaps between the stones so it can always leave."]],
        ["hero", ["Itu sebabnya batu-batu di Bukit Sembrani tidak tersusun rapat.", "That's why the stones on Sembrani Hill aren't set close together."]],
        ["inaSeli", ["Ya. Selama ratusan tahun, ia menjaga kawanan kuda liar dan membawa hujan tiap musim. Lalu orang bertopeng itu datang dengan benang hitam. Benang itu, Nak, adalah tali pertama yang pernah menyentuh lehernya.", "Yes. For hundreds of years it watched over the wild herds and brought rain every season. Then that masked man came with black thread. That thread, child, was the first rope that ever touched its neck."]],
        ["inaSeli", ["Bayangkan makhluk yang tak pernah diikat, tiba-tiba terjerat. Ia tidak menghitam karena jahat. Ia menghitam karena ketakutan. Kuda-kuda liar di sabana pun ikut panik. Tenangkan mereka dulu, lalu pergilah ke lingkaran batu itu.", "Imagine a creature never once bound, suddenly snared. It didn't turn black from evil. It turned black from terror. Even the wild horses on the savanna panicked with it. Calm them first, then go to the stone ring."]],
      ] },
      { tipe: "kalahkan", monster: "kudaLiar", need: 6, area: "sabana", tujuan: ["Tenangkan 6 Kuda Liar yang masih panik di Padang Sabana", "Calm 6 Wild Horses still panicking on the Savanna Plains"], baris: [
        ["narasi", ["Kuda liar terakhir berhenti menerjang. Ia mendengus, mengibaskan surainya yang basah oleh gerimis, lalu berlari kecil ke arah utara, ke Bukit Sembrani. Kawanannya menyusul satu per satu.", "The last wild horse stops charging. It snorts, shakes its drizzle-soaked mane, then trots north toward Sembrani Hill. Its herd follows one by one."]],
        ["hero", ["(Mereka pulang ke penjaganya.)", "(They're going home to their guardian.)"]],
      ] },
      { tipe: "prasasti", area: "sabana", dekat: "bos", tujuan: ["Cari tulisan tua di lingkaran batu Bukit Sembrani", "Find the old writing in the stone ring on Sembrani Hill"], baris: [
        ["narasi", ["Di salah satu batu megalit lingkaran Bukit Sembrani, di bawah lumut yang kini basah dan hijau, terpahat tulisan yang hampir terhapus angin.", "On one of the megaliths in the Sembrani Hill ring, beneath moss now wet and green, is an inscription nearly erased by the wind."]],
        ["narasi", ["'Kami yang menegakkan batu-batu ini tidak membangun kandang. Kami membangun tempat pulang. Celah di antara batu adalah pintu, dan pintu itu tak boleh ditutup selamanya.'", "'We who raised these stones did not build a pen. We built a place to come home to. The gaps between the stones are doors, and those doors must never be closed.'"]],
        ["narasi", ["'Siapa yang mengikat Sembrani akan kehilangan hujannya. Siapa yang membiarkannya bebas akan selalu didatangi awan.'", "'Whoever ties the Sembrani will lose its rain. Whoever leaves it free will always be visited by clouds.'"]],
        ["narasi", ["Di sebelah tulisan itu, ada bekas tapal kuda yang masih baru, terbenam dalam tanah basah. Di dekatnya, sehelai bulu putih panjang tersangkut di celah batu. Putih, bukan hitam lagi.", "Beside the writing are fresh hoofprints, sunk into the wet earth. Nearby, a long white feather is caught in a gap between the stones. White, no longer black."]],
        ["hero", ["Ia kembali ke sini... dan pergi lagi lewat celah batu. Pintunya masih terbuka.", "It came back here... and left again through the gap. The door is still open."]],
      ] },
      { tipe: "bicara", npc: "lewa", tujuan: ["Ceritakan kepada Lewa tentang bulu putih di bukit", "Tell Lewa about the white feather on the hill"], baris: [
        ["lewa", ["Hei, kau! Dari mana? Bajumu basah. ...Jangan bilang kau ke Bukit Sembrani tanpa aku!", "Hey, you! Where've you been? Your clothes are soaked. ...Don't tell me you went to Sembrani Hill without me!"]],
        ["hero", ["Ada bulu putih di lingkaran batu. Sembrani sudah putih lagi, Lewa.", "There was a white feather in the stone ring. The Sembrani is white again, Lewa."]],
        ["lewa", ["...Putih. Ibu selalu bilang ia putih. Waktu aku kecil, Ibu tersesat dalam badai pasir di sabana timur. Kudanya ketakutan dan tidak mau bergerak.", "...White. Mother always said it was white. When I was little, Mother got lost in a sandstorm on the eastern savanna. Her horse was terrified and wouldn't move."]],
        ["lewa", ["Lalu ada bayangan besar di atas badai. Sayap. Kudanya Ibu tiba-tiba tenang dan berjalan sendiri mengikuti bayangan itu, sampai ke pagar kampung. Ibu pulang dengan rambut penuh pasir dan senyum paling lebar yang pernah kulihat.", "Then there was a huge shadow above the storm. Wings. Mother's horse suddenly calmed and walked on its own, following that shadow, all the way to the village fence. Mother came home with her hair full of sand and the widest smile I've ever seen."]],
        ["lewa", ["Sejak itu aku belajar berkuda. Aku ingin suatu hari berkuda di bawah bayangan sayap itu. Waktu aku melihatnya hitam dan mengamuk, rasanya... seperti melihat cerita Ibu dirobek.", "That's when I learned to ride. I wanted to ride beneath those wings someday. When I saw it black and raging, it felt... like watching Mother's story being torn apart."]],
        ["hero", ["Ceritanya sudah tersambung lagi.", "The story's been stitched back together."]],
        ["lewa", ["Ya. Ya! Tadi malam, waktu aku menyikat Angin, ada bayangan besar lewat di atas awan. Angin meringkik senang. Kukira aku bermimpi. Ternyata tidak. Bilang Ina Seli, ya. Dia pasti mau menenun ini.", "Yes. Yes! Last night, while I was brushing Wind, a huge shadow passed above the clouds. Wind whinnied happily. I thought I was dreaming. Turns out I wasn't. Tell Ina Seli, okay? She'll want to weave this."]],
      ] },
      { tipe: "bicara", npc: "inaSeli", tujuan: ["Kembali kepada Ina Seli", "Return to Ina Seli"], baris: [
        ["hero", ["Ina, di lingkaran batu ada tulisan leluhur: siapa yang membiarkan Sembrani bebas akan selalu didatangi awan. Dan bulunya sudah putih lagi.", "Ina, there was an ancestral inscription in the stone ring: whoever leaves the Sembrani free will always be visited by clouds. And its feather is white again."]],
        ["inaSeli", ["Ah... Kalau begitu sumpah leluhur kami masih utuh. Kau tidak membunuhnya, Nak. Kau memutus talinya. Itu bedanya kau dengan orang bertopeng itu.", "Ah... Then our ancestors' oath is still whole. You didn't kill it, child. You cut its rope. That's the difference between you and that masked man."]],
        ["inaSeli", ["Lewa bercerita tentang ibunya? Hihi. Anak itu jarang menceritakan kisah yang satu itu. Ibunya penunggang terbaik di sabana. Keras kepala, ceplas-ceplos... Ama Doko jatuh cinta padanya justru karena itu.", "Lewa told you about her mother? Heehee. That girl rarely tells that particular story. Her mother was the finest rider on the savanna. Stubborn, outspoken... Ama Doko fell in love with her precisely because of that."]],
        ["inaSeli", ["Akan kutenun motif baru. Kuda putih di atas, badai di tengah, dan di bawahnya seorang anak yang memotong benang hitam. Supaya cucu-cucu kami tahu, sumpah itu pernah diuji dan bertahan.", "I'll weave a new motif. A white horse above, a storm in the middle, and beneath it a child cutting a black thread. So our grandchildren will know the oath was once tested, and held."]],
        ["inaSeli", ["Terimalah ini. Dan ingat, Nak: hal-hal paling berharga di dunia ini tidak bisa diikat. Hujan, kuda bersayap, hati orang. Kau hanya bisa membuat tempat yang membuat mereka ingin pulang.", "Take this. And remember, child: the most precious things in this world can't be tied down. Rain, winged horses, people's hearts. You can only make a place that makes them want to come home."]],
      ] },
    ],
  },

  // ===================== WATU GEDE =====================
  {
    id: "watuGede", npc: "amaDoko", monster: "watuGede",
    judul: ["Seribu Tangan", "A Thousand Hands"],
    syarat: () => S.bos && S.bos.watuGede,
    hadiah: { gold: 4200, exp: 30000, serpih: 7 },
    ringkas: ["Watu Gede adalah batu terbesar yang pernah ditarik leluhur Kampung Megalit, ditarik seribu orang selama empat puluh hari sambil bernyanyi, lalu ditanam di kaki Tugu Agung sebagai 'jantung' yang menyimpan nyanyian hujan. Saat tali penariknya putus di tanjakan, batu itu berhenti sendiri sejengkal sebelum menimpa seorang anak, kakek Ama Doko. Sejak itu orang percaya Watu Gede punya hati. Benang Dalang Sepi membangunkan dan menyeretnya, dan batu yang dulu menyelamatkan anak-anak dipaksa melawan mereka.", "Watu Gede is the largest stone the Megalith Village ancestors ever dragged, pulled by a thousand people for forty days while they sang, then set at the foot of the Great Pillar as a 'heart' that holds the rain song. When the hauling rope snapped on a slope, the stone stopped by itself a hand's breadth before crushing a child, Ama Doko's grandfather. Since then people believed Watu Gede had a heart. The Silent Puppeteer's threads woke and dragged it, and the stone that once saved a child was forced to fight against people."],
    langkah: [
      { tipe: "bicara", npc: "amaDoko", tujuan: ["Dengarkan kisah Ama Doko tentang Watu Gede", "Hear Ama Doko's tale of Watu Gede"], baris: [
        ["amaDoko", ["Kau. Duduk. Kerbau-kerbauku sudah pulang semua, hujan sudah turun, jadi hari ini aku punya waktu untuk bercerita. Jangan berharap ini sering terjadi.", "You. Sit. My buffalo are all home, the rain has come, so today I have time for a story. Don't expect it to happen often."]],
        ["amaDoko", ["Batu raksasa yang kau lawan di Tugu Agung itu. Watu Gede. Kau pikir itu cuma batu yang diberi nyawa oleh benang? Bukan. Batu itu sudah punya hati jauh sebelum benang mana pun.", "That giant stone you fought at the Great Pillar. Watu Gede. You think it's just a rock given life by thread? No. That stone had a heart long before any thread."]],
        ["amaDoko", ["Leluhur kami menarik batu-batu besar dari bukit untuk kubur dan tugu. Bukan dengan sihir. Dengan tali, kayu gelondong, dan ratusan orang yang bernyanyi bersama supaya tarikannya serempak.", "Our ancestors hauled great stones from the hills for tombs and pillars. Not with magic. With ropes, rolling logs, and hundreds of people singing together so they'd pull in unison."]],
        ["amaDoko", ["Watu Gede yang terbesar. Seribu orang. Empat puluh hari. Kata kakekku, nyanyian mereka terdengar sampai ke laut, dan batunya makin lama makin ringan, seolah ikut bernyanyi.", "Watu Gede was the largest. A thousand people. Forty days. My grandfather said their singing could be heard all the way to the sea, and the stone grew lighter and lighter, as if it were singing along."]],
        ["hero", ["Kakek Ama ikut menariknya?", "Your grandfather helped pull it?"]],
        ["amaDoko", ["Kakekku waktu itu masih bocah. Terlalu kecil untuk menarik. Tapi ia ada di sana. Dan karena itulah aku masih hidup hari ini. Ikut aku ke ujung kampung. Jalan tarik batu yang lama masih ada di sana.", "My grandfather was just a boy back then. Too small to pull. But he was there. And that's why I'm alive today. Come with me to the edge of the village. The old stone-hauling road is still there."]],
      ], tanya: [
        { tanya: ["Ama, apa benar batu bisa punya hati?", "Ama, can a stone really have a heart?"], jawab: [
          ["amaDoko", ["Kerbau bisa. Kuda bisa. Kenapa batu tidak? Kau pikir hati itu cuma milik yang bisa bicara? Kerbau-kerbauku tidak pernah bicara, tapi mereka tahu kapan aku sedih.", "Buffalo can. Horses can. Why not a stone? You think a heart only belongs to things that talk? My buffalo never say a word, but they know when I'm sad."]],
        ] },
      ] },
      // ke [8, 24]: petak rumput di padang barat daya kampung (x 8, y 24), terjangkau BFS dari Ama Doko (26, 18) & semua posisi jadwalnya
      { tipe: "pandu", npc: "amaDoko", area: "kampungBatu", ke: [8, 24], tujuan: ["Ikuti Ama Doko ke jalan tarik batu lama", "Follow Ama Doko to the old stone-hauling road"],
        ajak: ["Jalan. Dan jangan injak tahi kerbau, aku tidak mau mendengar keluhan.", "Walk. And don't step in the buffalo dung, I don't want to hear complaints."], baris: [
        ["amaDoko", ["Di sini. Lihat alur panjang di tanah ini, yang rumputnya tumbuh lebih rendah? Itu bekas gelondong kayu Watu Gede. Seratus tahun lebih, tanahnya masih ingat.", "Here. See this long groove in the ground, where the grass grows lower? That's where Watu Gede's rolling logs ran. Over a hundred years, and the earth still remembers."]],
        ["amaDoko", ["Pada hari ketiga puluh, di tanjakan menuju lembah, tali utamanya putus. Seribu orang terjengkang. Batu sebesar rumah itu mulai menggelinding mundur, ke arah anak-anak yang menonton di bawah.", "On the thirtieth day, on the slope toward the valley, the main rope snapped. A thousand people fell backward. That house-sized stone started rolling back, toward the children watching below."]],
        ["amaDoko", ["Kakekku tersandung dan jatuh tepat di jalurnya. Semua orang menjerit. Lalu... batu itu berhenti. Sejengkal dari kepala kakekku. Di tanah miring, tanpa tali, tanpa ganjalan. Berhenti begitu saja.", "My grandfather tripped and fell right in its path. Everyone screamed. Then... the stone stopped. A hand's breadth from my grandfather's head. On a slope, with no rope, no wedge. It just stopped."]],
        ["hero", ["Batu itu memilih berhenti.", "The stone chose to stop."]],
        ["amaDoko", ["Begitu kata kakekku sampai ia mati. Sejak itu Watu Gede tidak dipakai untuk kubur siapa pun. Para tetua menanamnya di kaki Tugu Agung sebagai jantung tugu, penyimpan nyanyian hujan.", "That's what my grandfather said until the day he died. After that, Watu Gede wasn't used for anyone's tomb. The elders set it at the foot of the Great Pillar as the pillar's heart, keeper of the rain song."]],
        ["amaDoko", ["Lalu orang bertopeng menyeretnya bangun dengan benang, dan batu yang dulu menyelamatkan anak kecil dipaksa memukul orang. Itu yang membuatku marah. Arwah tugu di sana masih gelisah. Tenangkan mereka. Lalu baca apa yang dipahat para tetua di kaki tugu.", "Then the masked man dragged it awake with thread, and the stone that once saved a little boy was forced to strike people. That's what makes me angry. The pillar spirits there are still restless. Calm them. Then read what the elders carved at the pillar's foot."]],
      ] },
      { tipe: "kalahkan", monster: "arwahTugu", need: 6, area: "tuguAgung", tujuan: ["Tenangkan 6 Arwah Tugu di Tugu Agung", "Calm 6 Pillar Spirits at the Great Pillar"], baris: [
        ["narasi", ["Arwah Tugu terakhir tidak memudar dalam diam. Sebelum lenyap, ia bersenandung. Nada rendah dan berat, berulang-ulang, seperti hitungan orang yang menarik sesuatu bersama-sama.", "The last Pillar Spirit doesn't fade in silence. Before vanishing, it hums. A low, heavy tune, repeating over and over, like the count of people pulling something together."]],
        ["hero", ["(Nyanyian tarik batu... Mereka masih mengingatnya.)", "(The stone-hauling song... They still remember it.)"]],
      ] },
      { tipe: "prasasti", area: "tuguAgung", dekat: "bos", tujuan: ["Cari pahatan para tetua di kaki Tugu Agung", "Find the elders' carving at the foot of the Great Pillar"], baris: [
        ["narasi", ["Di kaki Tugu Agung, di belakang tempat Watu Gede kini kembali duduk bersila, ada cekungan besar bekas ia dulu tertanam. Di dinding cekungan itu, terpahat ratusan tanda kecil berbentuk telapak tangan, berderet rapat.", "At the foot of the Great Pillar, behind the spot where Watu Gede now sits cross-legged again, is the great hollow where it was once set. On the hollow's wall, hundreds of small handprint marks are carved in tight rows."]],
        ["narasi", ["'Seribu tangan menarikmu. Seribu suara menyanyikanmu. Kau tidak lagi batu dari bukit. Kau adalah kami semua, yang bekerja bersama.'", "'A thousand hands drew you. A thousand voices sang you. You are no longer a stone from the hills. You are all of us, working together.'"]],
        ["narasi", ["'Pada hari tali putus, kau berhenti untuk seorang anak. Maka kami tidak akan menaruh orang mati di atasmu. Kau akan menjaga yang hidup. Simpanlah nyanyian kami, dan kembalikan kepada kami sebagai hujan.'", "'On the day the rope broke, you stopped for a child. So we will lay no dead upon you. You shall guard the living. Keep our song, and return it to us as rain.'"]],
        ["narasi", ["Di dasar cekungan, serpihan yang rontok dari tubuh Watu Gede saat pertarungan masih hangat. Saat kau menyentuhnya, terdengar dengung rendah, sama dengan senandung arwah tadi.", "At the bottom of the hollow, a chip that broke from Watu Gede during the battle is still warm. When you touch it, there's a low hum, the same as the spirits' humming."]],
        ["hero", ["Watu Gede masih di sini... dan nyanyian itu masih tersimpan di dalamnya.", "Watu Gede is still here... and that song is still kept inside it."]],
      ] },
      { tipe: "bicara", npc: "inaSeli", tujuan: ["Tanyakan kepada Ina Seli tentang nyanyian tarik batu", "Ask Ina Seli about the stone-hauling song"], baris: [
        ["hero", ["Ina, arwah di Tugu Agung bersenandung sebelum menghilang. Ama Doko bilang itu nyanyian tarik batu. Ina tahu lagunya?", "Ina, the spirits at the Great Pillar hummed before vanishing. Ama Doko says it's the stone-hauling song. Do you know it?"]],
        ["inaSeli", ["Tahu? Nak, aku menenunnya. Nyanyian itu tidak punya banyak kata. Hanya hitungan. Satu suara memanggil, seribu suara menjawab, lalu semua tangan menarik bersamaan.", "Know it? Child, I weave it. That song doesn't have many words. Only counting. One voice calls, a thousand voices answer, then every hand pulls at once."]],
        ["inaSeli", ["Lihat kain ini. Garis-garis kecil yang berulang di pinggirnya? Itu ketukan nyanyian tarik batu. Setiap penenun di kampung ini belajar polanya sebelum belajar motif lain.", "Look at this cloth. See the small repeating lines along its border? Those are the beats of the stone-hauling song. Every weaver in this village learns that pattern before any other motif."]],
        ["inaSeli", ["Orang bertopeng itu ingin dunia tanpa suara. Tapi lihat Watu Gede, Nak. Batu terbesar di negeri ini dipindahkan bukan oleh kekuatan satu orang, melainkan oleh suara yang saling menjawab.", "That masked man wants a world without voices. But look at Watu Gede, child. The greatest stone in this land was moved not by one person's strength, but by voices answering each other."]],
        ["inaSeli", ["Tanpa suara, seribu orang hanyalah seribu orang yang menarik ke arah berbeda. Sampaikan itu pada Ama Doko. Dia tidak suka mendengar hal-hal lembut dariku, tapi darimu mungkin dia mau.", "Without voices, a thousand people are just a thousand people pulling in different directions. Tell Ama Doko that. He doesn't like hearing soft things from me, but from you, he might."]],
      ] },
      { tipe: "bicara", npc: "amaDoko", tujuan: ["Kembali kepada Ama Doko", "Return to Ama Doko"], baris: [
        ["hero", ["Ama, para tetua memahat seribu telapak tangan di kaki tugu. Mereka menulis, Watu Gede bukan lagi batu, melainkan semua orang yang bekerja bersama. Dan serpihannya masih hangat, masih bersenandung.", "Ama, the elders carved a thousand handprints at the pillar's foot. They wrote that Watu Gede is no longer a stone, but all the people who worked together. And a chip of it is still warm, still humming."]],
        ["amaDoko", ["...Seribu tangan. Kakekku pasti ada di antara tanda-tanda itu. Dia ikut menarik waktu dewasa, kau tahu. Untuk membayar utang nyawanya, katanya.", "...A thousand hands. My grandfather must be among those marks. He pulled stones too when he grew up, you know. To repay the debt of his life, he said."]],
        ["amaDoko", ["Ina Seli bilang apa? Tanpa suara, seribu orang menarik ke arah berbeda? Hmph. Perempuan tua itu selalu benar, dan itu menyebalkan.", "What did Ina Seli say? Without voices, a thousand people pull in different directions? Hmph. That old woman is always right, and it's annoying."]],
        ["lewa", ["Ayah! Ayah bilang Ina Seli benar? Aku harus mencatat hari ini! Ayah tidak pernah bilang siapa pun benar!", "Father! You said Ina Seli was right? I have to mark this day! You never say anyone's right!"]],
        ["amaDoko", ["Diam, Lewa. ...Musim tanam nanti, kampung akan menarik batu lagi. Batu kecil saja, untuk menambal kaki Tugu Agung. Kami akan bernyanyi. Supaya Watu Gede mendengar bahwa kami masih ingat lagunya.", "Quiet, Lewa. ...Come planting season, the village will haul a stone again. Just a small one, to patch the foot of the Great Pillar. We'll sing. So Watu Gede hears that we still remember its song."]],
        ["amaDoko", ["Terimalah ini. Dan kalau musim tanam nanti kau lewat, bantu kami menarik. Tanganmu cukup kuat untuk menjatuhkan raksasa batu. Pasti cukup kuat untuk memindahkan satu batu kecil.", "Take this. And if you're passing by in planting season, help us pull. Your hands were strong enough to bring down a stone giant. Surely they're strong enough to move one little stone."]],
      ] },
    ],
  },

  // ===================== WEWE GOMBEL =====================
  {
    id: "weweGombel", npc: "rangkai", monster: "weweGombel",
    judul: ["Nenek di Balik Akar", "The Granny Behind the Roots"],
    syarat: () => S.bos && S.bos.weweGombel,
    hadiah: { gold: 4800, exp: 35000, serpih: 8 },
    ringkas: ["Menurut cerita rakyat Jawa yang dikenal di Semarang, Wewe Gombel adalah sosok yang menyembunyikan anak-anak yang diabaikan orang tuanya, lalu mengembalikan mereka setelah orang tuanya menyesal. Di Rimba Raya, Wewe dari Beringin Tua dulunya Nek Sambi, perempuan yang tak punya anak sendiri tetapi mengasuh semua yatim kampung rumah panjang, dan meminta dikubur di bawah beringin agar bisa terus menjaga anak yang tersesat. Tetua Rangkai kecil pernah ia sembunyikan tiga hari sampai ayahnya mencarinya sambil menangis. Ia melawan karena benang Dalang Sepi mencuri tawa anak-anak yang ia lindungi.", "In Javanese folklore known in Semarang, Wewe Gombel is a figure who hides children neglected by their parents, returning them once the parents repent. In the Great Rainforest, the Wewe of the Old Banyan was once Grandma Sambi, a woman with no children of her own who raised every orphan of the longhouse village, and asked to be buried under the banyan so she could keep watching over lost children. She once hid young Elder Rangkai for three days until his father came searching in tears. She fought because the Silent Puppeteer's thread was stealing the laughter of the children she protected."],
    langkah: [
      { tipe: "bicara", npc: "rangkai", tujuan: ["Dengarkan kisah Tetua Rangkai tentang Wewe Gombel", "Hear Elder Rangkai's tale of the Wewe Gombel"], baris: [
        ["rangkai", ["Duduklah di lantai rumah panjang ini, Nak. Dengar suara anak-anak di bawah sana? Mereka bermain lagi. Sudah lama aku tidak mendengar tawa sekeras itu.", "Sit on this longhouse floor, child. Hear the children down there? They're playing again. It's been a long time since I heard laughter that loud."]],
        ["rangkai", ["Aku sudah menceritakan legendanya sebelum kau ke Beringin Tua. Menurut cerita rakyat Jawa, yang terkenal di daerah Semarang, Wewe Gombel adalah sosok perempuan yang menyembunyikan anak-anak yang diabaikan atau diperlakukan buruk oleh orang tuanya.", "I told you the legend before you went to the Old Banyan. In Javanese folklore, best known around Semarang, the Wewe Gombel is a female figure who hides children who are neglected or mistreated by their parents."]],
        ["rangkai", ["Dalam cerita itu, ia tidak menyakiti anak-anak. Ia baru mengembalikan mereka setelah orang tuanya menyesal dan sungguh-sungguh mencari. Cerita itu dibawa ke sini oleh pedagang dari seberang, dan rimba kami menyimpannya dengan caranya sendiri.", "In that tale, she doesn't harm the children. She only returns them once the parents regret it and truly search for them. Traders from across the sea brought that story here, and our jungle kept it in its own way."]],
        ["rangkai", ["Tapi ada yang belum kuceritakan. Aku tahu Wewe dari Beringin Tua bukan karena legenda. Aku tahu karena... ia pernah menyembunyikanku.", "But there's something I haven't told you. I don't know the Wewe of the Old Banyan from legend. I know her because... she once hid me."]],
        ["hero", ["Tetua pernah disembunyikan Wewe?", "The Wewe once hid you, Elder?"]],
        ["rangkai", ["Waktu aku seumur Upik. Ayahku pemburu yang keras. Suatu malam ia memukulku karena aku menghilangkan mata tombaknya. Aku lari ke rimba sambil menangis. Ikut aku ke tepi sungai. Di sanalah cerita ini berakhir, dulu.", "When I was Upik's age. My father was a harsh hunter. One night he struck me because I'd lost his spearhead. I ran into the jungle crying. Come with me to the riverbank. That's where this story ended, back then."]],
      ], tanya: [
        { tanya: ["Tetua tidak takut waktu itu?", "Weren't you scared back then, Elder?"], jawab: [
          ["rangkai", ["Takut? Tentu. Nenek setinggi pohon pinang, rambutnya menjuntai sampai tanah. Tapi waktu ia mengusap kepalaku, tangannya lebih lembut dari tangan siapa pun di kampung. Anak kecil cepat tahu mana yang perlu ditakuti, Nak.", "Scared? Of course. A granny as tall as a palm tree, her hair hanging to the ground. But when she stroked my head, her hand was gentler than anyone's in the village. Little children learn quickly what's worth fearing, child."]],
        ] },
      ] },
      // ke [6, 24]: petak tanah di tepi sungai barat (x 6, y 24), terjangkau BFS dari Tetua Rangkai (17, 9) & semua posisi jadwalnya
      { tipe: "pandu", npc: "rangkai", area: "rumahPanjang", ke: [6, 24], tujuan: ["Ikuti Tetua Rangkai ke tepi sungai", "Follow Elder Rangkai to the riverbank"],
        ajak: ["Ke tepi sungai. Jalanku pelan, tapi tato di tanganku tahu jalannya.", "To the riverbank. I walk slowly, but the tattoos on my hands know the way."], baris: [
        ["rangkai", ["Di sini. Tiga hari aku tinggal di dalam akar Beringin Tua. Nenek Tinggi itu memberiku buah, menyanyikan lagu yang belum pernah kudengar, dan bercerita tentang bintang-bintang.", "Here. For three days I stayed inside the roots of the Old Banyan. The Tall Granny gave me fruit, sang songs I'd never heard, and told me stories about the stars."]],
        ["rangkai", ["Hari ketiga, ia membawaku ke tepi sungai ini. Ayahku ada di sini, berlutut di air, berteriak memanggil namaku sampai suaranya habis. Pemburu paling keras di kampung, menangis seperti bayi.", "On the third day, she brought me to this riverbank. My father was here, kneeling in the water, shouting my name until his voice gave out. The harshest hunter in the village, crying like a baby."]],
        ["rangkai", ["Nenek itu mendorong punggungku pelan. Aku lari ke ayahku. Waktu aku menoleh, ia sudah tidak ada. Hanya ada lingkaran biji buah di atas batu ini, seperti tanda.", "The granny gently pushed my back. I ran to my father. When I looked back, she was gone. There was only a ring of fruit seeds on this stone, like a sign."]],
        ["hero", ["Dan ayah Tetua?", "And your father, Elder?"]],
        ["rangkai", ["Ia tidak pernah mengangkat tangannya lagi kepadaku. Tidak sekali pun, sampai hari ia meninggal. Wewe tidak mengubahku, Nak. Ia mengubah ayahku. Itulah cara kerjanya.", "He never raised his hand to me again. Not once, until the day he died. The Wewe didn't change me, child. She changed my father. That's how she works."]],
        ["rangkai", ["Upik juga pernah bersama nenek itu. Tanyakan padanya apa yang ia lihat di dalam beringin. Anak-anak melihat hal yang tidak bisa dilihat orang tua.", "Upik was with that granny too. Ask her what she saw inside the banyan. Children see things grown-ups can't."]],
      ] },
      { tipe: "bicara", npc: "upik", tujuan: ["Tanyakan kepada Upik tentang Nenek Tinggi", "Ask Upik about the Tall Granny"], baris: [
        ["upik", ["Kak! Kak! Mau main tebak-tebakan? Kenapa ikan tidak bisa bicara? ...Karena mulutnya penuh air! Hihihi!", "Hey! Hey! Want to play riddles? Why can't fish talk? ...Because their mouths are full of water! Heehee!"]],
        ["hero", ["Upik, waktu kau di Beringin Tua, Nenek Tinggi itu bilang apa padamu?", "Upik, when you were at the Old Banyan, what did the Tall Granny say to you?"]],
        ["upik", ["Nenek bilang aku tidak boleh keluar dulu. Ada benang hitam yang berkeliaran mencari tawa anak-anak. Kalau tawanya diambil, anak itu jadi diam terus, kayak boneka.", "Granny said I couldn't go out yet. There was black thread roaming around, looking for children's laughter. If your laughter gets taken, you go quiet forever, like a doll."]],
        ["upik", ["Jadi Nenek menyembunyikan kami semua di sarang paling atas. Dia menyelimuti kami pakai rambutnya. Rambutnya hangat, Kak. Baunya kayak tanah habis hujan.", "So Granny hid all of us in the nests at the very top. She covered us with her hair. Her hair was warm. It smelled like earth after rain."]],
        ["upik", ["Tapi benangnya makin banyak, dan Nenek mulai kesakitan. Matanya jadi merah. Dia bilang, 'Lari, Nak, kalau Nenek berubah.' Aku tidak mau lari. Tapi Kakak datang.", "But the threads kept multiplying, and Granny started to hurt. Her eyes turned red. She said, 'Run, child, if Granny changes.' I didn't want to run. But then you came."]],
        ["upik", ["Kakak, Nenek tidak jahat, kan? Dia cuma kesepian dan kecapekan menjaga kami. Kalau Kakak ke beringin lagi, bilang Nenek, Upik sudah bisa tertawa keras lagi. Hihihi! Begini!", "She's not bad, right? She was just lonely and tired of guarding us. If you go back to the banyan, tell Granny that Upik can laugh loud again. Heehee! Like this!"]],
      ] },
      { tipe: "kalahkan", monster: "kalongRaksasa", need: 6, area: "beringin", tujuan: ["Usir 6 Kalong Raksasa yang masih gelisah di Beringin Tua", "Drive off 6 Giant Fruit Bats still restless at the Old Banyan"], baris: [
        ["narasi", ["Kalong terakhir berputar sekali di atas kepalamu, lalu menghilang di antara dahan. Untuk pertama kalinya, cahaya bulan menembus kanopi Beringin Tua dan jatuh ke akar-akarnya.", "The last bat circles once above your head, then vanishes among the branches. For the first time, moonlight pierces the Old Banyan's canopy and falls upon its roots."]],
      ] },
      { tipe: "prasasti", area: "beringin", dekat: "bos", tujuan: ["Cari tanda di akar Beringin Tua, di sarang Wewe dulu", "Find the marks on the Old Banyan's roots, at the Wewe's old nest"], baris: [
        ["narasi", ["Di akar terbesar Beringin Tua, tempat Wewe dulu bersarang, ada goresan-goresan yang terukir di kulit kayunya. Bukan huruf. Garis-garis kecil, ratusan banyaknya, masing-masing disertai sebuah lambang.", "On the Old Banyan's largest root, where the Wewe once nested, there are scratches cut into the bark. Not letters. Small lines, hundreds of them, each with a little symbol beside it."]],
        ["narasi", ["Kau mengenali beberapa lambangnya dari tato di tangan Tetua Rangkai: tanda keluarga kampung rumah panjang. Setiap garis adalah satu anak. Setiap anak yang dikembalikan pulang.", "You recognize some of the symbols from the tattoos on Elder Rangkai's hands: family marks of the longhouse village. Each line is one child. Each child returned home."]],
        ["narasi", ["Di dekat pangkal akar, terukir dengan tangan yang lebih rapi, ada tulisan tua: 'Aku Sambi. Rahimku kosong, tapi rumah panjang memberiku seratus anak yatim untuk diasuh. Kuburlah aku di bawah beringin. Aku belum selesai menjaga.'", "Near the base of the root, carved by a neater hand, is an old inscription: 'I am Sambi. My womb was empty, but the longhouse gave me a hundred orphans to raise. Bury me under the banyan. I am not done watching over them.'"]],
        ["narasi", ["Di antara ratusan garis itu, satu garis diberi lambang kecil berbentuk mata tombak. Di sebelahnya, garis paling baru, masih segar, dengan lambang berbentuk bunga kecil yang sedang tertawa.", "Among those hundreds of lines, one bears a tiny spearhead symbol. Beside it, the newest line, still fresh, has a symbol shaped like a small laughing flower."]],
        ["hero", ["Mata tombak... Tetua Rangkai. Dan yang ini pasti Upik.", "A spearhead... Elder Rangkai. And this one must be Upik."]],
        ["narasi", ["Angin lembut bertiup dari dalam akar. Sesaat, kau seperti mendengar seseorang bersenandung, rendah dan hangat, seperti lagu pengantar tidur.", "A gentle breeze blows from inside the roots. For a moment, you seem to hear someone humming, low and warm, like a lullaby."]],
      ] },
      { tipe: "bicara", npc: "rangkai", tujuan: ["Kembali kepada Tetua Rangkai", "Return to Elder Rangkai"], baris: [
        ["hero", ["Tetua, di akar beringin ada ratusan garis. Satu untuk setiap anak yang dikembalikan. Namanya Nek Sambi. Ada satu garis bertanda mata tombak.", "Elder, there are hundreds of lines on the banyan's root. One for each child returned. Her name was Grandma Sambi. One line is marked with a spearhead."]],
        ["rangkai", ["Sambi... Nek Sambi. Nenekku pernah bercerita tentang perempuan yang mengasuh semua yatim di rumah panjang ini, jauh sebelum aku lahir. Aku tidak pernah menyangka... itu dia.", "Sambi... Grandma Sambi. My grandmother once told me about a woman who raised every orphan in this longhouse, long before I was born. I never imagined... it was her."]],
        ["rangkai", ["Mata tombak. Hah. Ia bahkan ingat kenapa aku lari. Lima puluh tahun, dan ia masih ingat mata tombak yang hilang itu.", "A spearhead. Hah. She even remembered why I ran. Fifty years, and she still remembered that lost spearhead."]],
        ["hero", ["Upik bilang, Nek Sambi melawan karena benang Dalang mencuri tawa anak-anak. Ia menyembunyikan mereka untuk melindungi.", "Upik says Grandma Sambi fought because the Puppeteer's thread was stealing the children's laughter. She hid them to protect them."]],
        ["rangkai", ["Tentu saja. Ia tidak pernah mencuri anak, Nak. Ia meminjam mereka sebentar dari orang dewasa yang lupa cara menjaga. Malam ini, seluruh kampung akan membawa buah ke Beringin Tua. Biar Nek Sambi tahu, kami sudah ingat.", "Of course. She never stole children, child. She borrowed them for a while from grown-ups who forgot how to look after them. Tonight, the whole village will bring fruit to the Old Banyan. So Grandma Sambi knows we remember now."]],
        ["rangkai", ["Terimalah ini. Dan kalau suatu hari kau punya anak sendiri, ingat Nek Sambi. Jangan sampai ada nenek tinggi yang perlu meminjam mereka darimu.", "Take this. And if someday you have children of your own, remember Grandma Sambi. Don't ever let a tall granny need to borrow them from you."]],
      ] },
    ],
  },

  // ===================== YAKSA ES =====================
  {
    id: "yaksaEs", npc: "tenggo", monster: "yaksaEs",
    judul: ["Penjaga yang Kesepian", "The Lonely Guardian"],
    syarat: () => S.bos && S.bos.yaksaEs,
    hadiah: { gold: 5400, exp: 42000, serpih: 8 },
    ringkas: ["Dalam tradisi Hindu-Buddha, yaksa adalah makhluk raksasa penjaga. Yaksa Es menjaga Gua Es Bernyanyi, gerbang luar menuju Puncak Salju Abadi. Para porter gunung punya adat: bernyanyi di mulut gua agar sang penjaga membiarkan mereka lewat. Kakek Pak Tenggo, Mbah Darun, adalah satu-satunya porter yang pernah berbicara dengannya, dan tahu bahwa Yaksa itu kesepian, memahat arca-arca es sebagai teman. Dalang Sepi membekukan nyanyian gua dan menghidupkan arca-arca itu dengan benang, sehingga teman-teman sang penjaga berbalik melawannya.", "In Hindu-Buddhist tradition, a yaksa is a giant guardian being. The Ice Yaksa guarded the Singing Ice Cave, the outer gate to the Everlasting Snow Peak. Mountain porters kept a custom: sing at the cave mouth so the guardian would let them pass. Pak Tenggo's grandfather, Mbah Darun, was the only porter who ever spoke with it, and learned that the Yaksa was lonely, carving ice statues as companions. The Silent Puppeteer froze the cave's song and brought those statues to life with thread, turning the guardian's friends against it."],
    langkah: [
      { tipe: "bicara", npc: "tenggo", tujuan: ["Dengarkan kisah Pak Tenggo tentang Yaksa Es", "Hear Pak Tenggo's tale of the Ice Yaksa"], baris: [
        ["tenggo", ["Kau! Kau mengalahkannya! Raksasa es sebesar lumbung itu! Aku melihat dari balik batu. Lututku masih gemetar. Ini bukan karena dingin. ...Ya, ini karena takut.", "You! You beat it! An ice giant the size of a granary! I watched from behind a rock. My knees are still shaking. It's not the cold. ...Fine, it's fear."]],
        ["tenggo", ["Tapi sekarang aku bisa cerita. Kakekku, Mbah Darun, juga porter. Dia satu-satunya porter yang pernah bicara dengan Yaksa itu. Dan pulang dengan selamat, tentu saja. Kalau tidak, aku tidak akan ada di sini.", "But now I can tell it. My grandfather, Mbah Darun, was a porter too. He was the only porter who ever talked with that Yaksa. And came home safe, of course. Otherwise I wouldn't be here."]],
        ["tenggo", ["Nini Embun bilang, dalam tradisi Hindu-Buddha, yaksa adalah makhluk raksasa penjaga. Penjaga harta, penjaga hutan, penjaga gerbang. Arca penjaga pintu candi yang bermuka garang itu pun sering digambarkan begitu.", "Nini Embun says in Hindu-Buddhist tradition, a yaksa is a giant guardian being. Guardian of treasures, of forests, of gates. Those fierce-faced door-guardian statues at temple gates are often pictured that way too."]],
        ["hero", ["Seperti Dwarapala di Candi Wingit.", "Like the Dwarapala at Candi Wingit."]],
        ["tenggo", ["Nah, persis! Yaksa Es juga penjaga gerbang. Gerbang menuju puncak. Para porter punya adat: sebelum lewat mulut gua, kita harus bernyanyi. Lagu apa saja. Kalau gua menjawab dengan dentingan, artinya boleh lewat.", "Exactly! The Ice Yaksa was a gate guardian too. The gate to the peak. We porters have a custom: before passing the cave mouth, we must sing. Any song at all. If the cave answers with a chime, it means we may pass."]],
        ["tenggo", ["Mbah Darun suaranya jelek sekali. Fals, sumbang, seperti kambing tersedak. Tapi justru karena itu, Yaksa keluar menemuinya. Penasaran, katanya. Hehe. Kau mau tahu apa yang mereka bicarakan? Bersihkan dulu arca-arca di gua itu. Aku tidak mau cerita sambil diintip patung.", "Mbah Darun's voice was awful. Off-key, out of tune, like a choking goat. But that's exactly why the Yaksa came out to meet him. Out of curiosity, he said. Heh. Want to know what they talked about? Clear out those statues in the cave first. I don't want to tell it with statues peeking at me."]],
      ], tanya: [
        { tanya: ["Pak Tenggo sendiri pernah bernyanyi di mulut gua?", "Have you ever sung at the cave mouth yourself?"], jawab: [
          ["tenggo", ["Pernah. Sekali. Lalu guanya... berbunyi. Aku tidak menunggu untuk tahu bunyi apa. Sejak itu aku lewat jalur samping. Jangan bilang siapa-siapa.", "Once. Then the cave... made a sound. I didn't wait to find out what kind. Since then I take the side trail. Don't tell anyone."]],
        ] },
      ] },
      { tipe: "kalahkan", monster: "arcaEs", need: 6, area: "guaEs", tujuan: ["Hancurkan 6 Arca Es yang masih bergerak di Gua Es Bernyanyi", "Shatter 6 Ice Statues still moving in the Singing Ice Cave"], baris: [
        ["narasi", ["Arca Es terakhir retak dan runtuh. Di antara kepingannya, kau melihat sesuatu yang aneh: wajah arca itu dipahat dengan sangat teliti. Ada senyum kecil di sudut bibirnya, dan kerutan di matanya, seperti seseorang yang sedang mendengarkan lelucon.", "The last Ice Statue cracks and collapses. Among its fragments, you notice something strange: the statue's face was carved with great care. There's a small smile at the corner of its lips, and creases around its eyes, like someone listening to a joke."]],
        ["hero", ["(Ini bukan arca prajurit. Seseorang memahatnya sebagai... teman?)", "(This isn't a soldier statue. Someone carved it as a... friend?)"]],
      ] },
      { tipe: "prasasti", area: "guaEs", dekat: "bos", tujuan: ["Cari ukiran di dinding es dekat sarang Yaksa", "Find the carving on the ice wall near the Yaksa's lair"], baris: [
        ["narasi", ["Di dinding es dekat bekas singgasana Yaksa, ada dua ukiran. Yang pertama kasar dan besar, seperti digores dengan kuku raksasa. Yang kedua kecil dan miring, jelas dibuat dengan pisau manusia.", "On the ice wall near the Yaksa's old throne are two carvings. The first is rough and huge, as if scratched with a giant's claw. The second is small and crooked, clearly made with a human knife."]],
        ["narasi", ["Ukiran besar itu berbentuk lingkaran-lingkaran wajah: puluhan wajah es, masing-masing dengan ekspresi berbeda. Tertawa, menguap, mengantuk, cemberut. Di bawahnya, satu wajah besar sendirian, memandangi semuanya.", "The large carving is a circle of faces: dozens of ice faces, each with a different expression. Laughing, yawning, sleepy, sulking. Beneath them, one large face alone, gazing at them all."]],
        ["narasi", ["Ukiran kecil di sebelahnya berbunyi: 'Darun, porter, bersuara jelek. Raksasa ini menjaga gerbang seribu tahun dan tak pernah ada yang menemaninya. Ia memahat teman dari es. Aku berjanji akan datang tiap musim membawa lagu, sejelek apa pun.'", "The small carving beside it reads: 'Darun, porter, bad singer. This giant has guarded the gate a thousand years and no one ever kept it company. It carves friends out of ice. I promise to come every season bringing songs, however bad.'"]],
        ["narasi", ["Di bawahnya, dengan goresan yang lebih tua dan gemetar: 'Kakiku sudah tak kuat naik. Cucuku, Tenggo, penakut. Maaf, Kawan. Semoga ada yang bernyanyi untukmu.'", "Below it, in older, shakier strokes: 'My legs can no longer climb. My grandson, Tenggo, is a coward. Forgive me, friend. I hope someone sings for you.'"]],
        ["hero", ["Mbah Darun... Ia tidak pernah lupa janjinya.", "Mbah Darun... He never forgot his promise."]],
        ["narasi", ["Saat kau menyentuh ukiran itu, gua berdenting pelan. Satu nada, jernih, dari dalam es. Seperti jawaban.", "As you touch the carving, the cave chimes softly. One note, clear, from deep in the ice. Like an answer."]],
      ] },
      { tipe: "bicara", npc: "embun", tujuan: ["Tanyakan kepada Nini Embun tentang Yaksa dan Mbah Darun", "Ask Nini Embun about the Yaksa and Mbah Darun"], baris: [
        ["embun", ["Hihihi, kau habis dari gua lagi? Pipimu merah seperti apel. Ada apa, Nak?", "Heehee, back from the cave again? Your cheeks are red as apples. What is it, child?"]],
        ["hero", ["Nini, Yaksa Es memahat arca-arca itu sebagai teman. Dan Mbah Darun, kakek Pak Tenggo, berjanji bernyanyi untuknya tiap musim.", "Nini, the Ice Yaksa carved those statues as friends. And Mbah Darun, Pak Tenggo's grandfather, promised to sing for it every season."]],
        ["embun", ["Darun! Ah, Darun yang suaranya bisa membuat salju longsor. Aku ingat dia. Setiap musim kemarau ia naik membawa kopi dan lagu. Yaksa itu menunggunya seperti anak menunggu ayahnya pulang dari pasar.", "Darun! Ah, Darun, whose voice could cause avalanches. I remember him. Every dry season he climbed up with coffee and songs. That Yaksa waited for him like a child waiting for father to come home from market."]],
        ["embun", ["Yaksa itu bukan makhluk jahat. Ia penjaga luar. Tugasnya memastikan hanya orang yang bernyanyi, yang berhati riang, yang boleh naik ke wilayah Macan Putih. Orang yang datang membawa amarah tidak akan bernyanyi.", "That Yaksa isn't evil. It's the outer guardian. Its task is to make sure only those who sing, those with cheerful hearts, may climb into the White Tiger's domain. People who come carrying rage won't sing."]],
        ["embun", ["Lalu datang orang bertopeng yang tidak punya suara sama sekali. Ia tidak bisa bernyanyi. Yaksa bingung, Nak. Selama seribu tahun belum pernah ada tamu yang benar-benar diam. Ia membeku dalam kebingungan, dan benang itu masuk lewat celahnya.", "Then came a masked man with no voice at all. He couldn't sing. The Yaksa was confused, child. In a thousand years, no guest had ever been truly silent. It froze in its confusion, and the thread slipped in through the gap."]],
        ["embun", ["Pergilah ke Tenggo. Ceritakan ukiran kakeknya. Anak itu selalu merasa ia mengecewakan kakeknya karena penakut. Mungkin sudah waktunya ia tahu sesuatu.", "Go to Tenggo. Tell him about his grandfather's carving. That boy always felt he disappointed his grandfather by being a coward. Maybe it's time he learned something."]],
      ] },
      // ke [26, 21]: petak salju di sudut tenggara pondok (x 26, y 21), terjangkau BFS dari Pak Tenggo (20, 16) & semua posisi jadwalnya
      { tipe: "pandu", npc: "tenggo", area: "pondok", ke: [26, 21], tujuan: ["Ikuti Pak Tenggo ke tugu batu porter", "Follow Pak Tenggo to the porters' stone cairn"],
        ajak: ["Kakekku menulis tentang aku? ...Ayo, ikut aku ke tugu batu porter. Aku tidak mau menangis di depan Nini Embun.", "My grandfather wrote about me? ...Come with me to the porters' cairn. I don't want to cry in front of Nini Embun."], baris: [
        ["tenggo", ["Ini tugu batu porter. Setiap porter yang berhenti naik gunung meletakkan satu batu di sini. Batu yang paling atas itu punya Mbah Darun. Aku sendiri yang meletakkannya, waktu ia sudah tidak bisa berjalan.", "This is the porters' cairn. Every porter who stops climbing the mountain places one stone here. The topmost one is Mbah Darun's. I placed it myself, when he could no longer walk."]],
        ["hero", ["Mbah Darun menulis, 'Cucuku, Tenggo, penakut. Maaf, Kawan. Semoga ada yang bernyanyi untukmu.'", "Mbah Darun wrote, 'My grandson, Tenggo, is a coward. Forgive me, friend. I hope someone sings for you.'"]],
        ["tenggo", ["...Penakut. Ya. Itu benar. Dia minta aku menggantikannya bernyanyi di gua. Aku sudah sampai di mulut gua. Lalu ada dentingan dari dalam, dan aku lari sampai ke pondok tanpa berhenti.", "...Coward. Yes. That's true. He asked me to take his place singing at the cave. I made it to the cave mouth. Then there was a chime from inside, and I ran all the way to the lodge without stopping."]],
        ["tenggo", ["Tapi tunggu. Dentingan. Kalau gua berdenting, artinya boleh lewat. Yaksa itu... waktu itu ia menjawabku. Ia mengira aku Mbah Darun yang datang lagi. Dan aku lari.", "But wait. A chime. If the cave chimes, it means you may pass. That Yaksa... back then, it answered me. It thought I was Mbah Darun coming again. And I ran."]],
        ["tenggo", ["Bertahun-tahun ia menunggu. Lalu orang bertopeng datang, dan tidak ada siapa-siapa yang bernyanyi untuknya. Kalau aku tidak lari dulu...", "For years it waited. Then the masked man came, and there was no one to sing for it. If I hadn't run back then..."]],
        ["tenggo", ["Mulai musim depan, aku akan naik ke gua tiap musim. Bawa kopi. Bawa lagu. Suaraku lebih jelek dari Mbah Darun, tapi kepingan es di sana pasti mendengar. Terimalah ini, Kawan. Kau yang membuat porter penakut ini berani menepati janji kakeknya.", "Starting next season, I'll climb to the cave every season. Bring coffee. Bring songs. My voice is worse than Mbah Darun's, but the ice there will surely hear. Take this, friend. You're the one who made this cowardly porter brave enough to keep his grandfather's promise."]],
      ] },
    ],
  },

  // ===================== MACAN PUTIH =====================
  {
    id: "macanPutih", npc: "embun", monster: "macanPutih",
    judul: ["Gadis di Tengah Badai", "The Girl in the Blizzard"],
    syarat: () => S.bos && S.bos.macanPutih,
    hadiah: { gold: 6000, exp: 48000, serpih: 9 },
    ringkas: ["Menurut cerita rakyat di berbagai daerah Indonesia, macan putih adalah sosok penjaga tempat-tempat keramat. Macan Putih Puncak Salju Abadi menjaga atap dunia dan menimbang setiap pendaki lewat suaranya: ia mendengar isi hati dari nada bicara seseorang. Nini Embun kecil pernah naik gunung mencari ayahnya yang hilang, dan Macan Putih menggendongnya turun di tengah badai. Sejak itu Nini Embun tinggal di kaki puncak dan mendirikan pondok sebagai tempat singgah. Dalang Sepi yang tak bersuara tak bisa didengar oleh sang penjaga, sehingga ia lolos dan menjeratnya.", "In folklore across many regions of Indonesia, the white tiger is a guardian figure of sacred places. The White Tiger of the Everlasting Snow Peak guarded the roof of the world and weighed every climber by their voice, hearing the heart through the tone of one's speech. Young Nini Embun once climbed the mountain searching for her lost father, and the White Tiger carried her down through a blizzard. Since then Nini Embun has lived at the foot of the peak, founding the lodge as a resting place. The voiceless Silent Puppeteer couldn't be heard by the guardian, so he slipped past and snared it."],
    langkah: [
      { tipe: "bicara", npc: "embun", tujuan: ["Dengarkan kisah Nini Embun tentang Macan Putih", "Hear Nini Embun's tale of the White Tiger"], baris: [
        ["embun", ["Duduklah, Nak. Tidak, jangan di salju, nanti pantatmu beku. Di atas kulit domba ini. Hihihi. Nah. Hari ini aku tidak akan bercanda. Setidaknya tidak terlalu banyak.", "Sit, child. No, not on the snow, your bottom will freeze. On this sheepskin. Heehee. There. Today I won't joke. At least not too much."]],
        ["embun", ["Menurut cerita rakyat di berbagai daerah di Indonesia, macan putih adalah sosok penjaga. Penjaga hutan, gunung, atau tempat keramat. Di beberapa kisah ia dikaitkan dengan leluhur atau orang sakti. Orang menghormatinya, bukan memburunya.", "In folklore across many regions of Indonesia, the white tiger is a guardian figure. Guardian of forests, mountains, or sacred places. In some tales it's linked to ancestors or holy figures. People honor it rather than hunt it."]],
        ["embun", ["Macan Putih di puncak ini menjaga atap dunia. Ia tidak menimbang pendaki dari pedangnya atau hartanya. Ia menimbang dari suaranya. Dari nada bicaramu, ia mendengar isi hatimu. Bohong, takut, marah, rindu. Semuanya terdengar.", "The White Tiger on this peak guards the roof of the world. It doesn't weigh climbers by their swords or their wealth. It weighs them by their voice. In the tone of your speech, it hears your heart. Lies, fear, anger, longing. It hears them all."]],
        ["hero", ["Bagaimana Nini tahu sebanyak itu?", "How do you know so much, Nini?"]],
        ["embun", ["Karena ia pernah mendengarkan suaraku, Nak. Waktu aku masih gadis kecil, lebih kecil dari Upik. Ayahku porter. Suatu musim ia naik dan tidak pernah turun. Jadi aku naik mencarinya. Sendirian. Tanpa mantel.", "Because it once listened to my voice, child. When I was a little girl, smaller than Upik. My father was a porter. One season he climbed and never came down. So I climbed to find him. Alone. Without a coat."]],
        ["embun", ["Bodoh, ya? Hihi. Ceritanya panjang, dan puncak masih penuh roh salju yang gelisah. Tenangkan mereka dulu. Lalu pergilah ke tempat Macan Putih biasa berbaring. Ada sesuatu milikku di sana, sejak lama sekali. Lebih lama dari yang berani kau tebak.", "Foolish, wasn't it? Heehee. It's a long story, and the peak is still full of restless snow spirits. Calm them first. Then go to where the White Tiger used to lie. Something of mine has been there a very long time. Longer than you'd dare to guess."]],
      ], tanya: [
        { tanya: ["Nini, sebenarnya umur Nini berapa?", "Nini, how old are you really?"], jawab: [
          ["embun", ["Cukup tua untuk tahu bahwa pertanyaan itu tidak sopan, dan cukup muda untuk memaafkanmu. Hihihi! Sudah, minum teh jahemu.", "Old enough to know that question is impolite, and young enough to forgive you. Heehee! Now, drink your ginger tea."]],
        ] },
      ] },
      { tipe: "kalahkan", monster: "rohSalju", need: 7, area: "puncak", tujuan: ["Tenangkan 7 Roh Salju di Puncak Salju Abadi", "Calm 7 Snow Spirits on the Everlasting Snow Peak"], baris: [
        ["narasi", ["Roh Salju terakhir berputar pelan dan pecah menjadi butiran salju halus. Angin di puncak mendadak tenang. Di kejauhan, di atas punggung bukit, kau melihat sekelebat bayangan putih yang besar. Ia memandangmu sebentar, lalu menghilang.", "The last Snow Spirit swirls slowly and breaks into fine snowflakes. The wind on the peak suddenly calms. In the distance, atop a ridge, you glimpse a large white shadow. It watches you a moment, then vanishes."]],
      ] },
      { tipe: "prasasti", area: "puncak", dekat: "bos", tujuan: ["Cari tanda di tempat Macan Putih biasa berbaring", "Find the mark where the White Tiger used to lie"], baris: [
        ["narasi", ["Di batu datar tempat Macan Putih dulu berbaring, ada bekas cakar yang dalam, empat garis sejajar, sangat tua. Di sebelahnya, terukir dengan batu tajam, ada gambar yang dibuat tangan anak kecil.", "On the flat rock where the White Tiger once lay, there are deep claw marks, four parallel lines, very old. Beside them, scratched with a sharp stone, is a drawing made by a small child's hand."]],
        ["narasi", ["Gambarnya sederhana: seekor kucing besar bergaris, seorang anak perempuan di punggungnya, dan banyak titik-titik salju di sekeliling mereka. Di bawahnya, huruf-huruf besar dan miring: 'TRIMA KASIH PUTIH. AKU EMBUN. AKU AKAN JAGA KAKIMU.'", "The drawing is simple: a big striped cat, a little girl on its back, and many snow dots all around them. Beneath it, big, crooked letters: 'THANK YOU WHITE. I AM EMBUN. I WILL GUARD YOUR FEET.'"]],
        ["narasi", ["Di bawahnya lagi, dengan goresan yang jauh lebih baru dan rapi, seperti ditambahkan bertahun-tahun kemudian: 'Ayah tidak pernah ditemukan. Tapi Putih menemukanku. Itu sudah cukup.'", "Further below, in much newer, neater strokes, as if added years later: 'Father was never found. But White found me. That was enough.'"]],
        ["hero", ["'Aku akan jaga kakimu'... Kaki gunung. Itu sebabnya Nini Embun membangun pondok di bawah sana.", "'I will guard your feet'... The mountain's feet. That's why Nini Embun built the lodge down there."]],
        ["narasi", ["Sehelai bulu putih panjang tersangkut di bekas cakar itu, masih hangat. Seolah sang penjaga baru saja pergi, dan sengaja meninggalkannya untuk dibawa pulang.", "A long white hair is caught in the claw marks, still warm. As if the guardian had only just left, and left it on purpose to be carried home."]],
      ] },
      { tipe: "bicara", npc: "tenggo", tujuan: ["Tanyakan kepada Pak Tenggo apa yang porter ketahui tentang Macan Putih", "Ask Pak Tenggo what the porters know of the White Tiger"], baris: [
        ["tenggo", ["Bulu apa itu? Putih, panjang... Itu bulu macan? JANGAN DEKAT-DEKAT! ...Eh, maaf. Refleks porter. Boleh kupegang? Pelan-pelan.", "What's that hair? White, long... Is that a tiger's? DON'T COME CLOSER! ...Er, sorry. Porter reflex. May I hold it? Gently."]],
        ["tenggo", ["Para porter tidak pernah bicara keras soal Macan Putih. Bukan karena takut. Yah, sedikit takut. Tapi lebih karena hormat. Setiap porter punya cerita yang sama: tersesat dalam badai, lalu menemukan jejak kaki macan yang menuntun ke pondok.", "We porters never talk loudly about the White Tiger. Not from fear. Well, a little fear. But more from respect. Every porter has the same story: lost in a blizzard, then finding tiger tracks that lead to the lodge."]],
        ["tenggo", ["Jejaknya selalu berhenti di batas pondok. Tidak pernah masuk. Seperti ada perjanjian. Mbah Darun bilang, 'Macan itu mengantar, Nini Embun menyambut. Satu menjaga atas, satu menjaga bawah.'", "The tracks always stop at the edge of the lodge. Never enter. As if there were an agreement. Mbah Darun said, 'The tiger escorts, Nini Embun welcomes. One guards above, one guards below.'"]],
        ["hero", ["Waktu Nini Embun kecil, Macan Putih menggendongnya turun dari puncak di tengah badai.", "When Nini Embun was little, the White Tiger carried her down from the peak through a blizzard."]],
        ["tenggo", ["...Jadi begitu. Pantas Nini tidak pernah takut badai. Pantas ia selalu menyalakan pelita di jendela setiap malam badai. Itu bukan untuk kita. Itu untuk sahabatnya di atas sana.", "...So that's it. No wonder Nini's never afraid of storms. No wonder she always lights a lamp in the window every stormy night. It isn't for us. It's for her friend up there."]],
        ["tenggo", ["Bawa bulu itu ke Nini Embun. Pelan-pelan. Dan, eh... kalau kau naik lagi dan bertemu macannya, bilang Pak Tenggo titip salam. Dari jauh. Jauh sekali.", "Take that hair to Nini Embun. Gently. And, uh... if you go up again and meet the tiger, tell it Pak Tenggo sends regards. From far away. Very far away."]],
      ] },
      { tipe: "bicara", npc: "embun", tujuan: ["Bawa bulu Macan Putih kepada Nini Embun", "Bring the White Tiger's hair to Nini Embun"], baris: [
        ["hero", ["Nini, aku menemukan gambar Nini di batu Macan Putih. 'Aku akan jaga kakimu.' Dan ini... bulunya, masih hangat.", "Nini, I found your drawing on the White Tiger's rock. 'I will guard your feet.' And this... its hair, still warm."]],
        ["embun", ["...Oh. Oh, Putih. Gambarku masih ada? Huruf-hurufnya pasti jelek sekali. Aku belum bisa menulis waktu itu. Ayahku belum sempat mengajariku.", "...Oh. Oh, White. My drawing is still there? The letters must be so ugly. I couldn't write back then. My father never got the chance to teach me."]],
        ["embun", ["Malam itu aku menangis memanggil ayah sampai suaraku hampir habis. Macan itu mendengar suaraku. Ia tidak mendengar anak yang bodoh atau nekat. Ia mendengar anak yang rindu. Maka ia menggendongku turun.", "That night I cried calling for my father until my voice nearly gave out. The tiger heard my voice. It didn't hear a foolish or reckless child. It heard a child who missed her father. So it carried me down."]],
        ["embun", ["Kau tahu kenapa Dalang itu bisa lolos? Karena ia tidak punya suara, Nak. Putih tidak bisa mendengar isi hatinya. Dan hati yang tidak terdengar... itulah yang paling berbahaya, dan paling kesepian.", "Do you know why the Puppeteer could slip past? Because he had no voice, child. White couldn't hear his heart. And a heart that can't be heard... that's the most dangerous, and the loneliest."]],
        ["embun", ["Lucu, ya. Aku dan Ki Lirih sama-sama pernah menjerit sampai suara kami habis. Aku dijawab oleh seekor macan. Ia tidak dijawab siapa pun. Mungkin hanya itu bedanya kami berdua.", "Funny, isn't it. Ki Lirih and I both once screamed until our voices ran out. I was answered by a tiger. He was answered by no one. Maybe that's the only difference between us."]],
        ["embun", ["Terimalah ini. Bulunya biar kusimpan di dekat pelita jendela. Hihi, jangan menangis, Nak. Itu tugasku hari ini. Kau cukup menghabiskan tehmu.", "Take this. I'll keep the hair by the window lamp. Heehee, don't cry, child. That's my job today. You just finish your tea."]],
      ] },
    ],
  },

  // ===================== DALANG SEPI =====================
  {
    id: "dalangSepi", npc: "lirih", monster: "dalangSepi",
    judul: ["Tembang Asri", "The Song of Asri"],
    syarat: () => S.bos && S.bos.dalangSepi,
    hadiah: { gold: 7000, exp: 60000, serpih: 10 },
    ringkas: ["Dalang Sepi adalah Ki Lirih, dalang istana Prabu Kalamurka. Waktu kecil ia gagap dan ditertawakan, sehingga ia belajar berbicara lewat wayang; kelak suaranya menjadi yang paling lantang di istana, dan sang Prabu menjulukinya Ki Lirih sebagai lelucon. Ia menikahi pesinden istana, Nyi Asri, dan dikaruniai putra bernama Jati; ia juga memahat wayang kancil untuk Sekar kecil. Pada malam negeri Kalamurka jatuh ke dalam bayang, ia sedang pulang dari pentas, dan menjerit memanggil keluarganya di depan dinding bayang sampai suaranya hilang. Asri dan Jati tak pernah kembali. Tetapi tembang nina bobo yang Asri tulis untuk Jati selamat: muridnya, Nyi Ambar, sedang bernyanyi di Labuhan Lama saat negerinya tertutup bayang, dan menyanyikannya setiap senja menghadap ke barat. Lima abad kemudian, setiap pesinden Labuhan, termasuk Nyi Merdu, masih mempelajari Tembang Asri sebagai tembang pertama.", "The Silent Puppeteer is Ki Lirih, court puppeteer of King Kalamurka. As a child he stuttered and was laughed at, so he learned to speak through puppets; in time his voice became the loudest in the palace, and the King nicknamed him Ki Lirih, 'the Soft-Spoken', as a joke. He married the court singer, Nyi Asri, and had a son named Jati; he also carved a mouse-deer puppet for little Sekar. On the night Kalamurka's kingdom fell into shadow, he was returning from a performance, and screamed for his family before the wall of shadow until his voice was gone. Asri and Jati never came back. But the lullaby Asri wrote for Jati survived: her student, Nyi Ambar, was singing in the Old Harbor City when her homeland was sealed in shadow, and she sang it every dusk facing west. Five centuries later, every harbor singer, Nyi Merdu included, still learns the Song of Asri as her very first song."],
    langkah: [
      { tipe: "bicara", npc: "lirih", tujuan: ["Dengarkan Ki Lirih di depan Kelir Beku", "Listen to Ki Lirih before the Frozen Screen"], baris: [
        ["narasi", ["Ki Lirih berdiri memandangi kelir es. Saat kau mendekat, ia menoleh perlahan. Suaranya serak dan pelan, seperti bisikan dari ruangan sebelah. Setiap kata seolah harus ia pungut satu per satu dari tempat yang jauh.", "Ki Lirih stands gazing at the ice screen. As you approach, he turns slowly. His voice is hoarse and soft, like a whisper from the next room. Each word seems to be gathered one by one from somewhere far away."]],
        ["lirih", ["Kau. Anak yang memutus benang-benangku. ...Jangan khawatir. Aku tidak marah. Aku hanya... belum terbiasa mendengar suaraku sendiri. Lima ratus tahun, Nak. Suara ini terasa seperti baju orang lain.", "You. The child who cut my threads. ...Don't worry. I'm not angry. I'm only... not used to hearing my own voice. Five hundred years, child. This voice feels like someone else's clothes."]],
        ["lirih", ["Waktu kecil, aku gagap. Setiap kali aku bicara, anak-anak desa tertawa. Ayahku memberiku sebuah wayang kulit tua, dan lewat wayang, kata-kataku keluar lancar. Lama-lama suaraku tumbuh jadi yang paling lantang di istana. Prabu sampai menjulukiku Ki Lirih. Beliau suka lelucon semacam itu.", "As a child, I stuttered. Every time I spoke, the village children laughed. My father gave me an old leather puppet, and through it, my words came out smoothly. In time my voice grew into the loudest in the palace. The King even nicknamed me Ki Lirih, 'the Soft-Spoken'. He was fond of jokes like that."]],
        ["lirih", ["Aku menikahi pesinden istana, Nyi Asri. Suaranya... Nak, suaranya bisa membuat burung berhenti terbang untuk mendengarkan. Kami punya putra kecil. Jati. Anak itu tidak pernah bisa diam.", "I married the court singer, Nyi Asri. Her voice... child, her voice could make birds stop mid-flight to listen. We had a little son. Jati. That boy could never sit still."]],
        ["hero", ["Sekar bilang, Ki Lirih dulu memainkan wayang untuknya.", "Sekar said you used to perform puppet shows for her."]],
        ["lirih", ["Sekar kecil. Selalu duduk paling depan, terlalu dekat dengan blencong, lalu tertidur sebelum babak terakhir. Mari. Berjalanlah bersamaku sebentar. Kakiku sudah lama tidak berjalan tanpa benang yang menariknya.", "Little Sekar. Always sitting in the very front, too close to the oil lamp, then falling asleep before the last act. Come. Walk with me a while. My legs haven't walked without threads pulling them for a long time."]],
      ], tanya: [
        { tanya: ["Ki, kenapa Ki Lirih masih hidup setelah lima abad?", "Ki, how are you still alive after five centuries?"], jawab: [
          ["lirih", ["Malam itu bayang menyentuhku, Nak, tapi tidak menelanku. Ia hanya mengambil waktuku, sehingga aku tak menua lagi. Mungkin kesedihan yang terlalu besar ikut membekukannya, seperti es ini membekukan suara. Kurasa dunia belum mau melepaskanku sebelum aku belajar sesuatu. Dan hari ini aku sedang belajar.", "That night the shadow touched me, child, but did not swallow me. It only took my time, so I aged no more. Perhaps grief too great helped freeze it, the way this ice freezes sound. I think the world wouldn't let me go until I'd learned something. And today I am learning."]],
        ] },
      ] },
      // ke [38, 12]: petak salju di sisi timur pelataran atas kelir (x 38, y 12), terjangkau BFS dari Ki Lirih (24, 12); pelataran atas tidak bergantung pada teka-teki kelirWayang
      { tipe: "pandu", npc: "lirih", area: "kelir", ke: [38, 12], tujuan: ["Berjalanlah bersama Ki Lirih di pelataran Kelir Beku", "Walk with Ki Lirih across the Frozen Screen's terrace"],
        ajak: ["Pelan saja. Lima ratus tahun aku tidak pernah berjalan tanpa tujuan. Rasanya aneh dan menyenangkan.", "Slowly. For five hundred years I never walked without a purpose. It feels strange, and pleasant."], baris: [
        ["lirih", ["Untuk Sekar, aku memahat seekor kancil. Kecil, sebesar telapak tangannya. Ia membawanya ke mana-mana. Ia bahkan membuatkan suara untuk kancil itu, suara yang cempreng dan lucu. Seluruh istana tertawa.", "For Sekar, I carved a mouse-deer. Small, the size of her palm. She carried it everywhere. She even gave it a voice, a squeaky, funny voice. The whole palace laughed."]],
        ["lirih", ["Pada malam negeri kami jatuh ke dalam bayang, aku tidak ada di istana. Aku sedang pulang dari pentas. Waktu aku tiba di bukit, kota bawah tempat rumah kami berdiri sudah tertutup dinding hitam. Tidak ada pintu. Tidak ada celah.", "On the night our kingdom fell into shadow, I wasn't at the palace. I was returning from a performance. When I reached the hill, the lower town where our house stood was already enclosed by a black wall. No door. No gap."]],
        ["lirih", ["Aku menjerit. Asri. Jati. Asri. Jati. Semalaman. Sampai suaraku robek dan tak ada lagi yang keluar. Dan dari balik dinding itu, yang kudengar hanya gema sumpah-sumpah raja dan perintah-perintah perang.", "I screamed. Asri. Jati. Asri. Jati. All night long. Until my voice tore and nothing more came out. And from beyond that wall, all I heard were echoes of the king's oaths and orders of war."]],
        ["hero", ["Itu sebabnya Ki Lirih membenci kata-kata.", "That's why you came to hate words."]],
        ["lirih", ["Sumpah. Perintah. Hinaan. Kata-kata itulah yang menyalakan perang, pikirku. Tanpa kata, tak ada yang bisa menyakiti. Aku berjalan ke timur selama berabad-abad, mendaki sampai ke sini, dan menemukan kelir es yang membekukan setiap gema. Aku ingin seluruh dunia setenang kelir ini.", "Oaths. Orders. Insults. Those words lit the fires of war, I thought. Without words, no one could hurt anyone. I walked east for centuries, climbed all the way here, and found an ice screen that freezes every echo. I wanted the whole world as still as this screen."]],
        ["lirih", ["Wayang-wayang yang kuhidupkan masih berkeliaran di bawah. Mereka tidak tahu lakonnya sudah selesai. Bebaskan mereka, Nak. Lalu bacalah apa yang kutulis di kelir itu, malam pertama aku tiba. Aku tidak sanggup membacanya sendiri.", "The puppets I brought to life still roam below. They don't know the play is over. Free them, child. Then read what I wrote on the screen, the first night I arrived. I can't bear to read it myself."]],
      ] },
      { tipe: "kalahkan", monster: "wayangHidup", need: 8, area: "kelir", tujuan: ["Bebaskan 8 Wayang Hidup yang masih berkeliaran di Kelir Beku", "Free 8 Living Puppets still roaming the Frozen Screen"], baris: [
        ["narasi", ["Wayang Hidup terakhir berhenti bergerak. Benang hitamnya putus satu per satu, dan wayang itu jatuh perlahan ke salju, seperti dalang yang meletakkan wayangnya di kotak setelah lakon tamat.", "The last Living Puppet stops moving. Its black threads snap one by one, and the puppet drifts down onto the snow, like a puppeteer laying a puppet in its box after the play has ended."]],
        ["hero", ["(Tancep kayon. Lakonnya sudah selesai.)", "(The final curtain. The play is over.)"]],
      ] },
      { tipe: "prasasti", area: "kelir", dekat: "bos", tujuan: ["Baca tulisan Ki Lirih di dekat Kelir Beku", "Read Ki Lirih's writing near the Frozen Screen"], baris: [
        ["narasi", ["Di dasar kelir es, tertutup lapisan bunga es yang tebal, ada tulisan yang digores dengan ujung tangkai wayang. Hurufnya rapi, seperti tulisan orang yang terbiasa menulis naskah lakon.", "At the base of the ice screen, covered in a thick layer of frost flowers, is writing scratched with the tip of a puppet's rod. The letters are neat, like the hand of someone used to writing play scripts."]],
        ["narasi", ["'Untuk Asri dan Jati. Malam ini aku tiba di atap dunia. Aku tidak bisa memanggil nama kalian lagi. Jadi kutulis saja, di sini, di tempat suara membeku dan tak bisa hilang.'", "'For Asri and Jati. Tonight I arrived at the roof of the world. I can no longer call your names. So I write them here, where sound freezes and cannot be lost.'"]],
        ["narasi", ["'Asri, kau pernah bilang, tembang bisa menyeberangi tempat yang tak bisa diseberangi kaki. Aku tidak percaya lagi. Aku sudah berteriak ke dinding bayang semalaman, dan tak ada yang menyeberang.'", "'Asri, you once said a song can cross places feet cannot. I no longer believe it. I screamed at the wall of shadow all night, and nothing crossed.'"]],
        ["narasi", ["'Di bawah ini kusalin tembang yang kau tulis untuk Jati, waktu ia belum bisa tidur tanpa digendong. Supaya ada yang mengingatnya, walau hanya es.'", "'Below I copy the song you wrote for Jati, when he couldn't yet sleep without being held. So that something remembers it, even if only ice.'"]],
        ["narasi", ["Di bawahnya ada deretan notasi gamelan dan beberapa baris lirik pendek tentang bulan yang menunggu perahu pulang. Di ujungnya, satu kata yang ditulis berulang-ulang sampai hampir tak terbaca: 'Maaf.'", "Below that is a row of gamelan notation and a few short lines of lyrics about a moon waiting for a boat to come home. At the end, one word written over and over until it's nearly illegible: 'Sorry.'"]],
        ["hero", ["(Bulan yang menunggu perahu pulang... Rasanya aku pernah mendengar lagu seperti ini. Di pelabuhan. Nyi Merdu?)", "(A moon waiting for a boat to come home... I feel like I've heard a song like this. At the harbor. Nyi Merdu?)"]],
      ] },
      { tipe: "bicara", npc: "merdu", tujuan: ["Tanyakan kepada Nyi Merdu tentang tembang bulan dan perahu", "Ask Nyi Merdu about the song of the moon and the boat"], baris: [
        ["merdu", ["Kau datang! Dengar, dengar, aku bisa bicara sepanjang hari sekarang. Kemarin aku bernyanyi sampai subuh. Kadir datang mengetuk pintu, mengira ada pesta tanpa izin. Hihi!", "You came! Listen, listen, I can talk all day now. Yesterday I sang until dawn. Kadir came knocking, thinking there was an unlicensed party. Heehee!"]],
        ["hero", ["Nyi, apa Nyi tahu tembang tentang bulan yang menunggu perahu pulang?", "Nyi, do you know a song about a moon waiting for a boat to come home?"]],
        ["merdu", ["...Tembang Asri? Tentu saja. Itu tembang pertama yang dipelajari setiap pesinden Labuhan. Guruku belajar dari gurunya, dan gurunya dari gurunya lagi, terus sampai lima ratus tahun lalu.", "...The Song of Asri? Of course. It's the first song every harbor singer learns. My teacher learned it from hers, and she from hers, all the way back five hundred years."]],
        ["merdu", ["Ceritanya begini. Lima abad lalu, seorang pesinden muda dari negeri barat, Nyi Ambar, datang ke sini untuk bernyanyi di Pesta Laut. Selagi ia di sini, negerinya tertutup bayang, dan tak ada kapal yang bisa kembali ke sana.", "The story goes like this. Five centuries ago, a young singer from a western land, Nyi Ambar, came here to sing at the Sea Festival. While she was here, her kingdom was sealed in shadow, and no ship could sail back."]],
        ["merdu", ["Tembang itu milik gurunya, Nyi Asri, yang menulisnya untuk putra kecilnya. Setiap senja Nyi Ambar menyanyikannya di ujung dermaga, menghadap ke barat, supaya guru dan anak itu mendengar di mana pun mereka berada. Ia bernyanyi sampai tua, dan mewariskannya pada setiap muridnya.", "The song belonged to her teacher, Nyi Asri, who wrote it for her little son. Every dusk Nyi Ambar sang it at the end of the pier, facing west, so her teacher and the boy would hear it wherever they were. She sang until she was old, and passed it on to every student she had."]],
        ["hero", ["Nyi... Nyi Asri itu istri Ki Lirih. Dalang Sepi.", "Nyi... that Nyi Asri was Ki Lirih's wife. The Silent Puppeteer."]],
        ["merdu", ["...Dewa-dewa di langit. Orang yang mencuri suaraku... adalah suami dari perempuan yang tembangnya pertama kali kupelajari. Bawa ini, Nak. Kutuliskan tembang itu lengkap, dengan catatan guru-guruku. Ia harus tahu. Ia harus tahu bahwa tembang Asri tidak pernah berhenti dinyanyikan.", "...Heavens above. The man who stole my voice... is the husband of the woman whose song was the first I ever learned. Take this, child. I've written the song out in full, with my teachers' notes. He must know. He must know that Asri's song has never stopped being sung."]],
      ] },
      { tipe: "bicara", npc: "lirih", tujuan: ["Bawa Tembang Asri kepada Ki Lirih", "Bring the Song of Asri to Ki Lirih"], baris: [
        ["hero", ["Ki, tembang Nyi Asri tidak hilang. Muridnya, Nyi Ambar, membawanya ke Labuhan Lama. Lima ratus tahun para pesinden di sana menyanyikannya setiap senja, menghadap ke barat. Untuk Nyi Asri dan Jati.", "Ki, Nyi Asri's song was never lost. Her student, Nyi Ambar, carried it to the Old Harbor City. For five hundred years the singers there have sung it every dusk, facing west. For Nyi Asri and Jati."]],
        ["narasi", ["Ki Lirih tidak bergerak. Tangannya yang memegang lembaran tembang dari Nyi Merdu gemetar hebat. Lama sekali ia hanya menatap tulisan itu.", "Ki Lirih doesn't move. His hands holding Nyi Merdu's song sheet shake violently. For a long time he only stares at the writing."]],
        ["lirih", ["Ambar... gadis kecil yang selalu membawakan kotak selendang Asri. Ia selamat. Dan ia membawa tembang itu. Aku lewat di pelabuhan itu, Nak. Lima ratus tahun lalu, dalam perjalananku ke timur. Aku sudah tuli oleh dukaku sendiri. Aku tidak mendengar apa-apa.", "Ambar... the little girl who always carried Asri's box of scarves. She survived. And she carried that song. I passed through that harbor, child. Five hundred years ago, on my way east. I was deafened by my own grief. I heard nothing."]],
        ["lirih", ["Dan lima ratus tahun kemudian, aku mengirim orang-orangku untuk mencuri suara para pesinden di sana. Suara yang menyimpan tembang Asri. Aku hampir membungkam satu-satunya hal yang tersisa darinya.", "And five hundred years later, I sent my people to steal the voices of the singers there. The very voices that kept Asri's song. I nearly silenced the only thing left of her."]],
        ["lirih", ["Asri benar. Tembang bisa menyeberangi tempat yang tak bisa diseberangi kaki. Bahkan lima abad. Bahkan dinding bayang. Putri bilang Asri dan Jati sudah lama pulang ke langit. Tapi suara Asri masih tinggal di dunia, di mulut setiap pesinden Labuhan. Akulah yang menutup telinga.", "Asri was right. A song can cross places feet cannot. Even five centuries. Even a wall of shadow. The Princess says Asri and Jati went home to the sky long ago. But Asri's voice still lives in this world, in the mouth of every harbor singer. I was the one who closed my ears."]],
        ["lirih", ["Dulu aku bilang kata-kata bisa melukai. Itu benar. Tapi hanya kata-kata pula yang bisa meminta maaf, dan hanya tembang yang bisa menunggu selama ini. Aku akan tetap menjaga kelir ini. Tapi setiap senja, aku akan menghadap ke barat, dan menyanyikan tembang Asri. Dengan suaraku yang jelek ini.", "I once said words can wound. That's true. But only words can ask forgiveness, and only a song can wait this long. I will keep guarding this screen. But every dusk, I'll face west and sing Asri's song. With this poor voice of mine."]],
        ["lirih", ["Terimalah ini, Nak. Dari dalang tua yang akhirnya mendengar akhir lakonnya sendiri. Ternyata bukan Lakon Sunyi. Ternyata ini lakon tentang tembang yang tidak pernah berhenti dinyanyikan.", "Take this, child. From an old puppeteer who has finally heard the ending of his own play. It wasn't the Silent Play after all. It was a play about a song that never stopped being sung."]],
      ] },
    ],
  },
];
